COLLDATA("seeratency","ur",[[2833,"مَنْ سَرَّهُ أَنْ يَنْظُرَ إِلَى شَهِيْدٍ يَمْشِيْ عَلَى وَجْهِ الْأَرْضِ فَلْيَنْظُرْ إِلَى طَلْحَةَ بْنِ عُبَيْدِ اللهِ\n’’جو شخص زمین پر چلتے پھرتے شہید کو دیکھنا چاہتا ہے، وہ طلحہ بن عبید اللہ کو دیکھ لے۔‘‘(1)\nسیدنا طلحہ رضی اللہ عنہ سے روایت ہے کہ صحابہ کرام رضی اللہ عنہم نے ایک بدو سے کہا کہ تم رسول اللہ صلی اللہ علیہ وسلم سے یہ پوچھو کہ آیت کریمہ: ﴿مَنْ قَضَى نَحْبَهُ﴾ (الاحزاب 33:23) یعنی جنھوں نے اللہ سے جو عہد کیا تھا، وہ سچ کر دکھایا، سے کون لوگ مراد ہیں؟ چنانچہ اس دیہی شخص نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا تو آپ نے اسے کوئی جواب نہ دیا۔ ایسا تین مرتبہ ہوا۔ پھر اچانک میں مسجد کے دروازے میں داخل ہوا۔ میں نے سبز لباس پہنا ہوا تھا۔ جب رسول اللہ صلی اللہ علیہ وسلم نے مجھے دیکھا تو دریافت فرمایا:\nأَيْنَ السَّائِلُ عَمَّنْ قَضَى نَحْبَهُ؟\n’’عَمَّنْ قَضَى نَحْبَهُ کے بارے میں سوال کرنے والا کہاں ہے؟‘‘\nاس نے کہا: اے اللہ کے رسول! میں ہوں۔ تو آپ صلی اللہ علیہ وسلم نے (سیدنا طلحہ رضی اللہ عنہ کی طرف اشارہ کر کے) فرمایا:\n[تصویر: مسجد ابوطلحہ انصاری (بن غازی، لیبیا)]","",{"v":600258,"fn":"(1) جامع الترمذي: 3739، السيرة لابن هشام: 85/3","im":["v6_p258.jpg"]}],[2834,"هٰذَا مِمَّنْ قَضَى نَحْبَهُ\n’’یہ انھی میں سے ہے جنھوں نے اپنا عہد پورا کر لیا ہے۔‘‘(1)\n§سیدنا ابوطلحہ انصاری رضی اللہ عنہ کی شان سرفروشی\nسیدنا انس رضی اللہ عنہ کے اخیافی (سوتیلے) باپ ابوطلحہ انصاری رضی اللہ عنہ نے بھی بے مثال جاں نثاری کا مظاہرہ کیا۔ سیدنا ابوطلحہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کے آگے اپنے آپ کو سپر بنا لیا۔ وہ رسول اللہ صلی اللہ علیہ وسلم کے آگے کھڑے ہو کر اپنا سینہ سامنے کر دیا کرتے تھے تا کہ آپ صلی اللہ علیہ وسلم کو دشمن کے تیروں سے محفوظ رکھ سکیں۔ سیدنا انس رضی اللہ عنہ سے روایت ہے کہ احد کے دن لوگ شکست کھا کر رسول اللہ صلی اللہ علیہ وسلم کے پاس پہنچنے کے بجائے ادھر ادھر بھاگ گئے لیکن سیدنا ابوطلحہ رضی اللہ عنہ ایک ڈھال لے کر رسول اللہ صلی اللہ علیہ وسلم کے آگے سپر بن کر کھڑے ہو گئے۔ وہ ماہر تیرانداز تھے۔ بہت کھینچ کر تیر چلاتے تھے۔ اس دن انھوں نے دو یا تین کمانیں توڑ دیں۔ جو شخص ترکش لے کر ادھر سے گزرتا، نبی صلی اللہ علیہ وسلم اس سے فرماتے تھے:\n§انْثُرْهَا لِأَبِيْ طَلْحَةَ\n’’یہ ترکش ابوطلحہ کے لیے ڈال جاؤ۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم جب بھی نظر اٹھا کر لوگوں کو دیکھنا چاہتے تو ابوطلحہ عرض کرتے:\nيَا نَبِيَّ اللهِ بِأَبِيْ أَنْتَ وَأُمِّيْ، لَا تُشْرِفْ يُصِيْبُكَ سَهْمٌ مِنْ سِهَامِ الْقَوْمِ، نَحْرِيْ دُوْنَ نَحْرِكَ\n’’اے اللہ کے نبی! میرے ماں باپ آپ پر قربان ہوں، آپ اوپر نہ اٹھیں، مبادا دشمن کا کوئی تیر آپ کو لگ جائے۔ میرا سینہ آپ کے سینے کے لیے سپر کی طرح حاضر ہے۔‘‘(2)\nسیدنا انس رضی اللہ عنہ فرماتے ہیں کہ ابوطلحہ رضی اللہ عنہ اپنا اور نبی صلی اللہ علیہ وسلم کا ایک ہی ڈھال سے بچاؤ کر رہے تھے۔ ابوطلحہ رضی اللہ عنہ بہت اچھے تیرانداز تھے۔ جب وہ تیر چلاتے تو آپ صلی اللہ علیہ وسلم گردن اٹھا کر دیکھتے کہ ان کا تیر کہاں جا کر لگا ہے۔(3)\nایک روایت میں ہے کہ آپ صلی اللہ علیہ وسلم نے اس دن ابوطلحہ رضی اللہ عنہ کے بارے میں فرمایا:\nاَلصَّوْتُ أَبِيْ طَلْحَةَ فِي الْجَيْشِ أَشَدُّ عَلَى الْمُشْرِكِيْنَ مِنْ فِئَةٍ\n’’لشکر میں اکیلے ابوطلحہ کی آواز مشرکین پر ایک جماعت سے بھی بڑھ کر بھاری ہے۔‘‘(4)","",{"v":600259,"fn":"(1) جامع الترمذي: 3203\n(2) صحيح البخاري: 3811\n(3) صحيح البخاري: 2902\n(4) مسند أحمد: 203/3"}],[2835,"§سیدنا سعد بن ابی وقاص رضی اللہ عنہ کی تیراندازیاں\nنبی اکرم صلی اللہ علیہ وسلم پر اس دن جاں نثاری اور آپ کے ساتھ ثابت قدمی دکھانے والوں میں سعد بن ابی وقاص رضی اللہ عنہ بھی پیش پیش تھے۔ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو مشرکین کے پے در پے حملوں سے بچانے کے لیے جان لڑا دی۔ سیدنا سعد رضی اللہ عنہ کی بیٹی عائشہ بنت سعد اپنے والد سے اس دن کے احوال بیان کرتے ہوئے فرماتی ہیں کہ سیدنا سعد رضی اللہ عنہ فرماتے ہیں: جنگ احد کے روز جب مسلمانوں میں انتشار پھیل گیا تو میں الگ ہو کر بیٹھ گیا۔ سوچنے لگا کہ اب کیا کروں؟ بالآخر میں نے فیصلہ کیا کہ میں میدان سے بھاگوں گا نہ ہتھیار ڈالوں گا بلکہ کفار سے لڑتا رہوں گا یہاں تک کہ میں شہید ہو جاؤں یا ان مشرکوں سے نجات پا جاؤں۔ اچانک میں نے ایک آدمی کو دیکھا۔ میں اسے نہیں جانتا تھا۔ اس نے اپنا چہرہ ڈھانپ رکھا تھا۔ کفار نے ہر طرف سے اس شخص کا گھیراؤ کر رکھا تھا۔ اس نے اپنے ہاتھوں میں مٹی لی اور ان کی طرف پھینک دی۔ وہ سب کے سب ایکی ایڑیوں کے بل پیچھے ہٹ گئے حتیٰ کہ پہاڑ تک جا پہنچے۔ اس شخص نے کئی بار اس طرح کیا۔ میرے اور اس کے درمیان مقداد بن اسود رضی اللہ عنہ تھے۔ میں مقداد رضی اللہ عنہ سے اس شخص کے متعلق پوچھنے ہی لگا تھا کہ انھوں نے خود ہی کہہ دیا: اے سعد! یہ رسول اللہ صلی اللہ علیہ وسلم ہیں اور تمھیں یاد کر رہے ہیں۔ یہ سنا تھا کہ میں یک دم کھڑا ہو گیا۔ یوں لگا جیسے مجھے نئی زندگی مل گئی ہے اور مجھے کسی قسم کی کوئی تکلیف ہی نہیں۔ میں فوراً آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ رسول اللہ صلی اللہ علیہ وسلم نے مجھے اپنے سامنے بٹھا لیا۔ میں دشمن پر تیر چلانے لگا۔ جب بھی میں تیر چلاتا تو کہتا:\nاَللَّهُمَّ سَهْمُكَ، فَارْمِ بِهِ عَدُوَّكَ\n’’اے اللہ! یہ تیر تیرا ہے، اسے اپنے دشمن کے سینے میں پیوست کر دے۔‘‘\nیہ بات سن کر رسول اللہ صلی اللہ علیہ وسلم فرماتے تھے:\nاَللَّهُمَّ اسْتَجِبْ لِسَعْدٍ، اَللَّهُمَّ سَدِّدْ لِسَعْدٍ رَّمْيَتَهُ، إِيْهَا سَعْدًا فِدَاكَ أَبِيْ وَأُمِّيْ\n’’اے اللہ! سعد کی دعا قبول فرما۔ اے اللہ! سعد کا تیر نشانے پر لگے۔ اے سعد! اور تیر پھینک، میرے ماں باپ تجھ پر فدا ہوں۔‘‘(1)\nسیدنا سعد رضی اللہ عنہ نے اپنے آپ کو رسول اللہ صلی اللہ علیہ وسلم پر فدا کر دیا تو اس کے صلے میں یہ یگانہ اعزاز پایا کہ آپ صلی اللہ علیہ وسلم نے یہ ارشاد فرمایا: ’’تم پر میرے ماں باپ قربان ہوں۔‘‘ احد کے روز آپ صلی اللہ علیہ وسلم نے ان کے سامنے سارے تیر بکھیر","",{"v":600260,"fn":"(1) جامع الترمذي: 3751، المستدرك للحاكم: 26/3، حدیث: 4314، واللفظ له"}],[2836,"دیے اور فرمایا:\nيَا سَعْدًا اِرْمِ فِدَاكَ أَبِيْ وَأُمِّيْ\n’’اے سعد! تجھ پر میرے ماں باپ فدا ہوں، تیر چلاؤ۔‘‘(1)\nسیدنا علی رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کبھی کسی کے لیے اپنے ماں باپ قربان کرنے کے الفاظ مبارک نہیں کہے سوائے سعد بن ابی وقاص رضی اللہ عنہ کے۔(2)\nاحد کے روز سیدنا سعد رضی اللہ عنہ نے ایک ہی تیر سے تین مشرکین مکہ کو جہنم رسید کر دیا تھا۔(3)\nامام زہری فرماتے ہیں کہ اس روز سیدنا سعد رضی اللہ عنہ نے لشکر کفار پر ایک ہزار تیر برسائے۔ مشرکین کے مشہور تیراندازوں میں سے ایک شخص حبان بن عرقہ تھا۔ اُس کا ایک تیر رسول اللہ صلی اللہ علیہ وسلم کی خادمہ ام ایمن رضی اللہ عنہا کے دامن پر آ لگا جس سے پردہ اٹھ گیا۔ وہ اس وقت زخمی مجاہدوں کو پانی پلا رہی تھیں۔ اللہ کے دشمن حبان نے ایک مسلمان خاتون کی بے پردگی پر قہقہہ لگایا تو رسول اللہ صلی اللہ علیہ وسلم بے حد آزردہ اور بے قرار ہو گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا سعد رضی اللہ عنہ کو پھل کے بغیر ایک تیر دیا اور حکم دیا: (اِرْمِ بِهِ) ’’اسے چلاؤ‘‘۔ سعد رضی اللہ عنہ نے وہ تیر چلایا تو وہ سیدھا حبان کے گلے پر جا لگا جس سے وہ گر گیا اور اس کے ستر سے پردہ اٹھ گیا۔ اب رسول اللہ صلی اللہ علیہ وسلم کے لب مبارک پر ایسا تبسم ظاہر ہوا کہ آپ کے دندان مبارک نظر آنے لگے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\nاِسْتَقَادَ لَهَا سَعْدٌ، أَجَابَ اللهُ دَعْوَتَكَ وَسَدَّدَ رَمْيَتَكَ\n’’سعد نے اس (ام ایمن رضی اللہ عنہا) کا بدلہ لے لیا۔ اللہ تعالیٰ تیری دعا قبول فرمائے اور تیرا ہر تیر نشانے پر بیٹھے۔‘‘(4)\n§ابودجانہ رضی اللہ عنہ کی جاں نثاری\nجب مشرکین نے رسول اللہ صلی اللہ علیہ وسلم کو چاروں طرف سے گھیر لیا تو ابودجانہ رضی اللہ عنہ سپر بن کر آپ صلی اللہ علیہ وسلم کے سامنے کھڑے ہو گئے اور پشت دشمنوں کی طرف کر دی۔ دشمن کے تیر پر تیر چلے آتے تھے مگر ابودجانہ رضی اللہ عنہ اس اندیشے سے ذرا بھی حرکت نہ کرتے تھے مبادا آپ صلی اللہ علیہ وسلم کو کوئی تیر لگ جائے۔(5)","",{"v":600261,"fn":"(1) صحيح البخاري: 4055، صحيح مسلم: 2412\n(2) صحيح البخاري: 4059، صحيح مسلم: 2411، جامع الترمذي: 3755\n(3) زاد المعاد: 205/3\n(4) المغازي للواقدی: 215/1، سبل الهدى والرشاد: 201/4\n(5) السيرة لابن إسحاق: 337/1"}],[2837,"§سہل بن حنیف رضی اللہ عنہ کی موت پر بیعت\nسیدنا ابوسعد سہل بن حنیف بن واہب اوسی انصاری رضی اللہ عنہ بھی رسول اللہ صلی اللہ علیہ وسلم کے ساتھ احد کے میدان میں ثابت قدم رہے۔ انھوں نے اس دن رسول اللہ صلی اللہ علیہ وسلم کے ہاتھ پر موت کی بیعت کی اور اس کے بعد مشرکین کو رسول اللہ صلی اللہ علیہ وسلم کی ذات گرامی سے دور دھکیل دیا۔ امام حاکم فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم احد کے روز فرماتے تھے:\nنَبِّلُوا سَهْلًا، فَإِنَّهُ سَهْلٌ\n’’سہل (رضی اللہ عنہ) کو تیر دو۔ ان کے لیے تیر چلانا آسان ہے۔‘‘(1)\nاسی طرح نبی اکرم صلی اللہ علیہ وسلم نے احد کے دن اُس وقت بھی ان کی شجاعت کی تعریف فرمائی جب سیدنا علی رضی اللہ عنہ نے اپنی تلوار سیدہ فاطمہ رضی اللہ عنہا کو دھونے کے لیے دی اور کہا کہ اس نے آج حق ادا کیا ہے تو نبی صلی اللہ علیہ وسلم نے فرمایا:\nلَئِنْ كُنْتَ صَدَقْتَ الْقِتَالَ لَقَدْ صَدَقَ مَعَكَ سَهْلُ بْنُ حُنَيْفٍ وَأَبُوْ دُجَانَةَ\n’’اگر تم نے قتال کے جوہر دکھائے ہیں تو یقیناً تمھارے ساتھ سہل بن حنیف اور ابودجانہ نے بھی لڑائی میں شان شجاعت دکھائی ہے۔‘‘(2)\n§حاطب بن ابی بلتعہ رضی اللہ عنہ کی شان شجاعت\nرسول اللہ صلی اللہ علیہ وسلم کے ساتھ جن لوگوں نے انتہائی جان لیوا حالات میں ثابت قدمی دکھائی، ان میں سے ایک عظیم مجاہد حاطب بن ابی بلتعہ رضی اللہ عنہ بھی ہیں۔\nعتبہ بن ابی وقاص نے رسول اللہ صلی اللہ علیہ وسلم کو چار پتھر مارے جس سے آپ کا نیچے والا دایاں رباعی دانت مبارک شہید ہو گیا۔ حاطب بن ابی بلتعہ رضی اللہ عنہ فرماتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کا دانت مبارک شہید ہوا تو میں آپ صلی اللہ علیہ وسلم کی خدمت میں پہنچا۔ میں نے آپ سے پوچھا کہ یہ حرکت کس نے کی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ عتبہ بن ابی وقاص نے۔ میں نے پوچھا: وہ کدھر گیا ہے؟ آپ صلی اللہ علیہ وسلم نے ایک طرف اشارہ کیا تو میں اسی طرف دوڑ پڑا۔ وہ جلد ہی مل گیا۔ میں نے اس پر تلوار کا وار کر کے اس کی گردن کاٹ ڈالی۔ پھر میں نے اس کا سر اٹھایا اور اس کا گھوڑا پکڑ کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہو گیا۔ آپ صلی اللہ علیہ وسلم نے یہ صورت حال دیکھ کر مجھے دو مرتبہ یہ دعا دی:\nرَضِيَ اللهُ عَنْكَ، رَضِيَ اللهُ عَنْكَ","",{"v":600262,"fn":"(1) المستدرك للحاكم: 409/3، حدیث: 5734\n(2) السيرة لابن هشام: 106/3، دلائل النبوة للبيهقي: 283,284/3، المستدرك للحاكم: 504/4\n(3) السيرة النبوية لابن كثير، ص: 316"}],[2838,"[تصویر: مدرسہ عبد الرحمن بن عوف للتعليم الأساسي للبنين]\n’’اللہ تم سے راضی ہو، اللہ تم سے راضی ہو۔‘‘(1)\n§سیدنا عبدالرحمن بن عوف رضی اللہ عنہ کی ثابت قدمی\nاحد کے روز آزمائش کے وقت رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ثابت قدم رہنے والوں میں عبدالرحمن بن عوف رضی اللہ عنہ بھی شامل ہیں۔ انھوں نے آپ کی حفاظت کے لیے تیر اندازی کی یہاں تک کہ انھیں تلوار کے بیس سے زیادہ زخم آئے۔ ان کے منہ پر بھی چوٹ لگی جس سے ان کا سامنے والا دانت ٹوٹ گیا۔ انھیں بہت گہرے زخم آئے تھے، ان میں سے ایک زخم ٹانگ پر بھی لگا تھا جس کی وجہ سے وہ لنگڑے ہو گئے تھے۔(2)\n§قتادہ بن نعمان رضی اللہ عنہ کی سرگزشت\nقتادہ بن نعمان رضی اللہ عنہ فرماتے ہیں کہ احد کے روز میں رسول اللہ صلی اللہ علیہ وسلم کے سامنے کھڑا ہو گیا اور اپنا چہرہ دشمنوں کی طرف پھیر دیا تا کہ دشمنوں کے تیر میرے چہرے پر پڑیں اور آپ کا چہرہ مامون و محفوظ رہے۔ عین اس حالت میں کہ دشمن تیروں کی بوچھاڑ کر رہے تھے، دشمنوں کا ایک تیر میری آنکھ پر ایسا لگا کہ آنکھ کا ڈھیلا باہر نکل پڑا۔ میں اسی وقت اپنی آنکھ کے ڈھیلے کو ہاتھ میں لیے نبی صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا۔ رسول اللہ صلی اللہ علیہ وسلم میری حالت دیکھ کر آبدیدہ ہو گئے اور آپ صلی اللہ علیہ وسلم نے میرے لیے یہ دعا کی:","",{"v":600263,"fn":"(1) المستدرك للحاكم: 340/3، السنن الكبرى للبيهقي: 308/6، موسوعة الغزوات الكبرى لباشميل: 258/1، إمتاع الأسماع: 162,163/1\n(2) السيرة لابن هشام: 88/3، موسوعة الغزوات الكبرى لباشميل: 260/1","im":["v6_p263.jpg"]}],[2839,"اَللَّهُمَّ! إِنَّ قَتَادَةَ قَدْ أَوْجَهَ نَبِيَّكَ بِوَجْهِهِ، فَاجْعَلْهَا أَحْسَنَ عَيْنَيْهِ، وَأَحَدَّهُمَا نَظَرًا\n’’اے اللہ! قتادہ نے تیرے نبی کے چہرے کی اپنے چہرے کے ذریعے سے حفاظت کی ہے، تو اس کی آنکھ کو پہلے سے بھی زیادہ خوبصورت اور تیز تر بنا دے۔‘‘\nاس کے معاً بعد نبی صلی اللہ علیہ وسلم نے اپنے دست مبارک سے قتادہ رضی اللہ عنہ کا باہر نکلا ہوا ڈھیلا اس کی جگہ پر رکھ دیا۔ ان کی آنکھ اسی وقت بالکل ٹھیک بلکہ پہلے سے بھی بہتر اور تیز بینائی والی ہو گئی۔(1)\nایک روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قتادہ رضی اللہ عنہ سے فرمایا:\nإِنْ شِئْتَ صَبَرْتَ وَلَكَ الْجَنَّةُ، وَإِنْ شِئْتَ رَدَدْتُهَا وَدَعَوْتُ اللهَ تَعَالَى لَكَ\n’’اگر تو صبر کرے تو تیرے لیے جنت ہے اور اگر چاہے تو میں اسے اسی جگہ رکھ کر تیرے لیے دعا کروں۔‘‘\nقتادہ رضی اللہ عنہ عرض گزار ہوئے: اے اللہ کے رسول! بلاشبہ جنت بہت بڑا انعام ہے اور جلیل القدر عطیہ ہے۔ لیکن میری بیوی مجھ سے بہت محبت کرتی ہے۔ مجھے اندیشہ ہے کہ اگر میری بیوی نے مجھے موجودہ شکل میں دیکھ لیا تو وہ کہیں مجھ سے نفرت نہ کرنے لگے۔ آپ مجھ پر شفقت فرماتے ہوئے میری آنکھ کا ڈھیلا اپنے مبارک ہاتھوں سے اس کی جگہ پر رکھ دیجیے۔ آپ صلی اللہ علیہ وسلم نے اپنے دست مبارک سے آنکھ کا ڈھیلا پکڑ کر اس کی جگہ پر رکھ دیا اور یہ دعا کی:\nاَللَّهُمَّ أَكْسِهِ جَمَالًا\n’’اے اللہ! اسے حسن و جمال عطا فرما۔‘‘\nسیدنا قتادہ رضی اللہ عنہ نے یہ بھی درخواست کی کہ آپ میرے لیے اللہ تعالیٰ سے جنت کی دعا کر دیجیے۔ آپ صلی اللہ علیہ وسلم نے ان کے لیے جنت کی دعا بھی کی۔ یوں سیدنا قتادہ رضی اللہ عنہ کی آنکھ بحال ہو گئی۔(2)\n§جنتی مومن کی یلغار\nسیدنا جابر رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے احد کے دن رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: اے اللہ کے رسول!\nأَرَأَيْتَ إِنْ قُتِلْتُ فَأَيْنَ أَنَا؟\n’’مجھے یہ بتائیں کہ اگر میں قتل کر دیا جاؤں تو میرا ٹھکانا کہاں ہوگا؟‘‘","",{"v":600264,"fn":"(1) المعجم الكبير للطبراني: 8/19، دلائل النبوة للبيهقي: 483,484/2، السيرة لابن إسحاق: 337/1\n(2) دلائل النبوة للبيهقي: 251-253/3، السيرة الحلبية: 542/2، الروض الأنف: 271/3"}],[2840,"آپ صلی اللہ علیہ وسلم نے فرمایا:\nفِيْ الْجَنَّةِ\n’’جنت میں۔‘‘\nاس وقت اس صحابی کے ہاتھ میں کھجوریں تھیں۔ انھوں نے اُسی وقت وہ کھجوریں پھینک دیں اور مشرکوں پر ٹوٹ پڑے یہاں تک کہ شہید ہو گئے۔(1)\n§ام عمارہ نسیبہ بنت کعب رضی اللہ عنہا کا جہاد\nقبیلہ خزرج کی ایک شاخ بنو نجار سے تعلق رکھنے والی ایک محترم خاتون سیدہ ام عمارہ نسیبہ بنت کعب رضی اللہ عنہا نے رسول اللہ صلی اللہ علیہ وسلم کی عین اس وقت حفاظت کی جب ابن قمیہ نے رسول اللہ صلی اللہ علیہ وسلم پر حملہ کیا تھا۔ اس عظیم خاتون کی نبی صلی اللہ علیہ وسلم سے اس وقت اولین ملاقات ہوئی جب مکہ مکرمہ میں انصار رضی اللہ عنہم کے ایک وفد نے نبی صلی اللہ علیہ وسلم کے ہاتھ پر بیعت کی تھی۔ بیعت کرنے والے اس عالی مقام وفد میں دو خواتین بھی شامل تھیں۔ ان میں سے ایک سیدہ ام عمارہ رضی اللہ عنہا تھیں۔ وہ اپنے خاوند غزیہ بن عمرو اور اپنے دو بیٹوں حبیب اور عبداللہ کے ساتھ اس مبارک مجلس میں موجود تھیں۔ غزوہ احد کے موقع پر یہ عظیم المرتبت خاتون 44 سال کی تھیں۔ جب مشرکین مکہ احد میں خیمہ زن ہوئے تو یہ اپنے دونوں بیٹوں اور خاوند کے ساتھ میدان کارزار میں جا پہنچیں۔ عورتوں کے ذمے زخمیوں کو پانی پلانے اور اُن کی مرہم پٹی کرنے کی ڈیوٹی تھی، ان کے پاس بھی پانی کا مشکیزہ تھا۔ یہ شروع دن سے آخر تک میدان جنگ میں ڈٹی رہیں اور پیاسے مجاہدین کو پانی پلاتی رہیں۔\nسیدہ ام سعد بنت سعد بن ربیع رضی اللہ عنہا ایک مرتبہ ان کے پاس گئیں اور عرض کیا: خالہ جان! ذرا غزوہ احد کے بارے میں کچھ بتائیں۔ آپ نے اس جنگ میں کس طرح حصہ لیا؟\nام عمارہ رضی اللہ عنہا فرمانے لگیں: غزوۂ احد کے روز میں صبح سویرے ہی نکل پڑی۔ میدان جنگ میں پہنچی۔ میں لڑائی دیکھنا چاہتی تھی۔ میرے پاس پانی کا مشکیزہ بھی تھا۔ میں چلتے چلتے اللہ کے رسول صلی اللہ علیہ وسلم کی خدمت میں پہنچ گئی۔ آپ صلی اللہ علیہ وسلم صحابہ کرام رضی اللہ عنہم کے ساتھ تشریف فرما تھے۔ مسلمان غالب تھے اور فتح مندی سے سرشار تھے۔ پھر عقب سے خالد بن ولید نے اچانک مسلمانوں پر حملہ کر دیا، بڑی کھلبلی مچی۔ میں اُسی وقت اللہ کے رسول صلی اللہ علیہ وسلم کی خدمت میں جا پہنچی اور عملاً جہاد میں شریک ہو گئی۔ میں نے تلوار اور کمان سنبھالی اور رسالت مآب صلی اللہ علیہ وسلم کا دفاع کرنے لگی یہاں تک کہ میں زخمی ہو گئی۔","",{"v":600265,"fn":"(1) صحيح البخاري: 4046، مسند أحمد: 308/3"}],[2841,"ام سعد رضی اللہ عنہا کہتی ہیں کہ میں نے ان کے کندھے پر گہرا زخم دیکھا تو پوچھا: آپ کو یہ زخم کس نے لگایا تھا؟ انھوں نے جواب دیا: ابن قمیہ نے۔ اللہ اسے ذلیل و رسوا کرے۔ جب لوگ بھاگ گئے تو ابن قمیہ یہ کہتا ہوا آگے بڑھا کہ مجھے بتاؤ محمد کہاں ہیں؟ اگر وہ زندہ بچ گئے تو میں خائب و خاسر ہو گیا۔ یہ بڑا نازک وقت تھا۔ اس وقت میں نے اور مصعب بن عمیر اور دیگر صحابہ کرام رضی اللہ عنہم نے، جو اللہ کے رسول صلی اللہ علیہ وسلم کے آس پاس مستعد کھڑے تھے، آپ صلی اللہ علیہ وسلم کا دفاع کیا۔ ہم لوگ آپ صلی اللہ علیہ وسلم کی حفاظت کرتے ہوئے مشرکین کے خلاف ڈٹ گئے۔ ابن قمیہ نے مجھ پر ضرب لگائی، میں نے بھی اسے مارا لیکن اللہ کے دشمن ابن قمیہ نے اوپر تلے دو زرہیں پہن رکھی تھیں۔ (اس لیے میرا وار کارگر نہ ہوا)(1)\nرسول اللہ صلی اللہ علیہ وسلم کا کیا حال ہے؟\nجب ابن قمیہ نے سیدہ ام عمارہ رضی اللہ عنہا کے کندھے پر تلوار کا وار کیا تو سیدہ غش کھا کر گر پڑیں۔ پھر جونہی انھیں ہوش آیا تو انھوں نے فوراً بے تابی سے پوچھا: اللہ کے رسول صلی اللہ علیہ وسلم کا کیا حال ہے؟ آپ صلی اللہ علیہ وسلم کہاں ہیں؟ مشرکین نے آپ کے ساتھ کیا سلوک کیا؟ صحابہ کرام رضی اللہ عنہم نے کہا: الحمد للہ، آپ خیریت سے ہیں۔\nسیدنا عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا۔ آپ صلی اللہ علیہ وسلم فرما رہے تھے:\nمَا الْتَفَتُّ يَمِيْنًا وَلَا شِمَالًا يَوْمَ أُحُدٍ إِلَّا وَأَنَا أَرَاهَا تُقَاتِلُ دُوْنِيْ\n’’احد کے دن جب بھی میں نے دائیں بائیں دیکھا تو ام عمارہ ہی کو اپنے آگے مصروف جنگ پایا۔‘‘(2)\n§ماں بیٹا نبی صلی اللہ علیہ وسلم کے دفاع میں\nعبداللہ بن زید بن عاصم رضی اللہ عنہما کہتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ غزوہ احد میں شریک ہوا۔ جب لوگ ادھر اُدھر منتشر ہو گئے تو میں اور میری والدہ آپ صلی اللہ علیہ وسلم کا دفاع کرنے لگے۔ آپ صلی اللہ علیہ وسلم نے مجھ سے دریافت فرمایا:\nاِبْنَ أُمِّ عُمَارَةَ؟\n’’کیا تم ام عمارہ کے بیٹے ہو؟‘‘\nمیں نے عرض کیا: جی ہاں! آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اِرْمِ‘‘ تیر مارو! میں نے مشرکین میں سے ایک آدمی کو پتھر مارا۔ وہ گھوڑے پر سوار تھا، پھر اس کے گھوڑے کی آنکھ میں جا لگا، گھوڑا ڈگمگا گیا۔ اس کا سوار دھڑام سے نیچے گر گیا۔ میں اس","",{"v":600266,"fn":"(1) المغازي للواقدی: 235/1، السيرة لابن هشام: 86,87/3\n(2) فتح الباري: 97,98/6"}],[2842,"پر سنگ باری کرتا رہا یہاں تک کہ میں نے اسے زخمی کر دیا۔ رسول اللہ صلی اللہ علیہ وسلم یہ منظر دیکھ رہے تھے اور مسکرا رہے تھے۔ عبداللہ بن زید رضی اللہ عنہ بیان کرتے ہیں کہ ابن قمیہ نے جب میری والدہ کے کندھے پر تلوار کا وار کیا تو بڑا گہرا زخم آیا۔ رسول اللہ صلی اللہ علیہ وسلم نے جب ان کے کندھے پر زخم دیکھا تو اپنی نگرانی میں ان کی مرہم پٹی کرائی۔ پھر فرمایا:\n«أُمَّكَ، أُمَّكَ، أَعْصِبْ جُرْحَهَا، بَارَكَ اللهُ عَلَيْكُمْ مِنْ أَهْلِ الْبَيْتِ، مَقَامُ أُمِّكَ خَيْرٌ مِنْ مَقَامِ فُلَانٍ وَفُلَانٍ، رَحِمَكُمُ اللهُ أَهْلَ الْبَيْتِ، وَمَقَامُ رَبِيبِكَ، يَعْنِي زَوْجَ أُمِّهِ، خَيْرٌ مِنْ مَقَامِ فُلَانٍ وَفُلَانٍ، رَحِمَكُمُ اللهُ أَهْلَ الْبَيْتِ»\n’’اپنی ماں کے پاس جلدی سے جاؤ۔ ان کی مرہم پٹی کرو، تمھارے گھرانے کو اللہ تعالیٰ بابرکت بنائے۔ تمھاری والدہ کا مقام فلاں فلاں کے مقام سے بھی برتر ہے۔ اللہ تعالیٰ تمھارے گھرانے پر رحم فرمائے اور تمھارے ربیب، یعنی تمھاری والدہ کے خاوند کا مقام فلاں فلاں شخص کے مقام سے بھی بلند تر ہے۔ اللہ تعالیٰ تمھارے گھرانے پر رحم فرمائے۔‘‘\n§ام عمارہ رضی اللہ عنہا کے لیے دعائے نبوی\nگویا یہ عظیم الشان خراج تحسین اور یہ نادر دعا رسول اللہ صلی اللہ علیہ وسلم کی طرف سے سیدہ ام عمارہ رضی اللہ عنہا کے لیے تمغہ بسالت تھا۔ ام عمارہ رضی اللہ عنہا کے بیٹوں کے جوش ایمانی نے بھی اس رفیع الشان موقع سے خوب فائدہ اٹھایا۔ شدید زخمی ہونے کے باوجود وہ اپنے لیے دنیا کے بجائے آخرت کی تمنا کرنے لگیں۔ انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے درخواست کی:\n«أَدْعُ اللهَ أَنْ تُرَافِقَكَ فِي الْجَنَّةِ»\n’’(اے اللہ کے رسول!) یہ دعا کیجیے کہ ہمیں جنت میں آپ کی معیت کا شرف حاصل ہو۔‘‘\nاللہ کے رسول صلی اللہ علیہ وسلم نے معاً یہ دعا کی:\n«اللَّهُمَّ اجْعَلْهُمْ رُفَقَائِي فِي الْجَنَّةِ»\n’’اے اللہ! انھیں جنت میں میری رفاقت عطا فرما۔‘‘\nسیدہ ام عمارہ رضی اللہ عنہا یہ دعا سن کر خوشی سے نہال ہو گئیں۔ کہنے لگیں:\n«مَا أُبَالِي مَا أَصَابَنِي مِنَ الدُّنْيَا»\n’’اب مجھے دنیا کی کسی مصیبت کی کوئی پروا نہیں۔‘‘","",{"v":600267}],[2843,"§بیٹے کو جہاد کی ولولہ انگیز تلقین\nسیدہ ام عمارہ رضی اللہ عنہا کا بیٹا عبداللہ جو اس جنگ میں شریک تھا، زخمی ہوا تو انھوں نے اپنے لخت جگر کے زخم پر پٹی باندھی اور کہا: بیٹا! اب تمھارے زخم پر پٹی کر دی گئی ہے۔ یہ موقع بیٹھ کر زخم دیکھنے اور اپنے اندر احساس کمتری پیدا کرنے کا نہیں۔ دیکھو! خود رسول اللہ صلی اللہ علیہ وسلم بنفس نفیس میدان جنگ میں موجود ہیں۔ تمھیں اپنے زخم دیکھ کر اپنے آپ پر ضعف کے آثار طاری کرنا زیب نہیں دیتا۔ جاؤ پوری قوت سے دشمن پر ٹوٹ پڑو۔ یا خود ختم ہو جاؤ یا دشمنان اسلام کو نیست و نابود کر دو۔\nغزوہ احد سے واپسی کے اگلے روز اللہ کے رسول صلی اللہ علیہ وسلم صحابہ کرام رضی اللہ عنہم کے ساتھ حمراء الاسد تشریف لے گئے۔ مقصد یہ تھا کہ اگر دشمن واپسی کی چال چلے تو اس سے راستے ہی میں نمٹ لیا جائے۔ رسول اللہ صلی اللہ علیہ وسلم نے اعلان فرمایا:\n«أَنْ لَا يَخْرُجَنَّ مَعَنَا أَحَدٌ إِلَّا مَنْ حَضَرَ يَوْمَنَا بِالْأَمْسِ»\n’’ہمارے ساتھ صرف وہی لوگ چلیں جو میدان احد میں موجود تھے۔‘‘\nچونکہ ام عمارہ رضی اللہ عنہا بھی میدان احد میں موجود تھیں، اس لیے یہ بھی روانہ ہونے لگیں مگر ان کا زخم بہت گہرا تھا۔ وہ انتہائی درد انگیز اذیت سے بے قرار تھیں، اس لیے زخموں کے علاج اور درد کی شدت کی وجہ سے وہ نبی صلی اللہ علیہ وسلم کے ساتھ جانے کی حسرت پوری نہ کر سکیں۔ لیکن جب رسول اللہ صلی اللہ علیہ وسلم غزوہ حمراء الاسد سے واپس تشریف لائے تو اپنے گھر تشریف لے جانے سے پہلے\n[تصویر: حمراء الاسد کا ایک منظر]","",{"v":600268,"im":["v6_p268.jpg"]}],[2844,"آپ صلی اللہ علیہ وسلم نے سیدنا عبداللہ بن کعب المازنی رضی اللہ عنہ کو سیدہ ام عمارہ رضی اللہ عنہا کی خیریت دریافت کرنے کے لیے بھیجا۔(1) انھوں نے واپس آ کر بتایا کہ اب ان کی حالت بہتر ہے۔ یہ خبر سن کر رسول اللہ صلی اللہ علیہ وسلم نے بڑی خوشی کا اظہار فرمایا۔\n§بھاگنے والوں کو ام ایمن رضی اللہ عنہا کی زجر و توبیخ\nبعض مؤرخین نے لکھا ہے کہ گھمسان کی لڑائی کے وقت مسلمانوں کی کچھ عورتیں امدادی کارروائی کے لیے تیار ہو گئیں۔ ان عورتوں میں رسول اللہ صلی اللہ علیہ وسلم کی آیا ام ایمن رضی اللہ عنہا بھی تھیں۔ جب میدان کارزار سے بھاگ آنے والے مسلمانوں نے مدینہ میں داخل ہونے کا ارادہ کیا، اس وقت رسول اللہ صلی اللہ علیہ وسلم میدان جنگ ہی میں ڈٹے کھڑے تھے۔ اس نازک وقت میں سیدہ ام ایمن رضی اللہ عنہا نے ان شکست خوردہ لوگوں کو دیکھا تو وہ ان کے چہروں پر اپنی مٹھیوں سے مٹی پھینکنے لگیں۔ انھوں نے انھیں زجر و توبیخ کرتے ہوئے فرمایا: تکلا لے لو اور اپنی تلوار مجھے دے دو، میں جہاد کرنے جاتی ہوں۔\n§محمد صلی اللہ علیہ وسلم شہید ہو گئے تو اللہ تو حی و قیوم ہے\nسیدنا مالک بن دخشم رضی اللہ عنہ، سیدنا خارجہ بن زید رضی اللہ عنہ کے پاس سے گزرے۔ ان کی انتڑیاں زخمی تھیں اور انھیں بڑے شدید تیرہ (13) زخم لگے تھے۔ مالک رضی اللہ عنہ کہنے لگے: کیا آپ کو علم ہے کہ محمد صلی اللہ علیہ وسلم شہید ہو گئے ہیں تو خارجہ رضی اللہ عنہ نے فوراً فرمایا:\n«فَإِنْ كَانَ مُحَمَّدٌ قَدْ قُتِلَ فَإِنَّ اللهَ حَيٌّ لَا يَمُوتُ فَقَدْ بَلَّغَ مُحَمَّدٌ، فَقَاتِلْ عَنْ دِينِكَ»\n’’اگر رسول اللہ صلی اللہ علیہ وسلم شہید ہو گئے ہیں تو اللہ تو زندہ ہے۔ وہ کبھی نہیں مر سکتا۔ رسول اللہ صلی اللہ علیہ وسلم نے بلاشبہ ہم تک دین ربانی پہنچا کر اپنا فرض ادا کر دیا۔ اب تم لوگ اپنے دین کی خاطر لڑو۔‘‘(2)\n§انصاری کی جاں نثاری\nابن اسحاق کہتے ہیں: مسلمانوں کے انتشار کے بعد سب سے پہلے جو صاحب آئے، وہ قیس بن محرث تھے۔ وہ انصار کے ایک گروہ کے ساتھ آئے تھے۔ مشرکین نے یکبارگی حملہ کیا تو قیس مشرکوں سے ٹکرا گئے۔ مشرکین نے انھیں نیزے مار کر شہید کر دیا۔(3)\nاس موقع پر حباب بن منذر رضی اللہ عنہ نے پکارا: اے آل سلمہ! اس پکار پر وہ سب اسی وقت حاضر ہو گئے اور کہنے لگے: اے اللہ کے داعی! ہم حاضر خدمت ہیں۔","",{"v":600269,"fn":"(1) المغازي للواقدي: 235-238/1\n(2) إمتاع الأسماع: 165/1\n(3) الإصابة: 378/5"}],[2845,"عباس بن عبادہ، خارجہ بن زید اور اوس بن ارقم رضی اللہ عنہم نے پوری قوت سے نعرہ تکبیر لگایا اور میدان جہاد میں کود پڑے۔ عباس رضی اللہ عنہ کہنے لگے: اے مسلمانوں کی جماعت! اللہ اور اس کے نبی کی طرف رجوع کرو۔ یہ جو تمھیں نقصان پہنچا ہے تو اس کی وجہ صرف یہ ہے کہ تم نے نبی صلی اللہ علیہ وسلم کی نافرمانی کی ہے۔ انھوں نے تمھیں تاکید فرمائی تھی کہ اگر صبر کرو گے تو کامیاب رہو گے مگر تم ایسا نہ کر سکے۔ پھر انھوں نے اپنا خود اور زرہ اتار دی۔ پھر خارجہ رضی اللہ عنہ سے پوچھا: کیا تمھیں ان کی ضرورت ہے؟ خارجہ رضی اللہ عنہ نے کہا: نہیں، میں بھی وہی چاہتا ہوں جو تم چاہتے ہو، چنانچہ دونوں میدان جہاد میں مشرکین سے لڑنے لگے۔ عباس رضی اللہ عنہ کہہ رہے تھے: اگر رسول اللہ صلی اللہ علیہ وسلم کو کچھ ہو گیا اور ہم\n[تصویر: میدان احد میں جانثاری اور سرفروشی دکھانے والے بعض صحابہ کرام رضی اللہ عنہم کا شجرہ]\nشجرے کا مرکزی سلسلہ: ثعلبہ، حارثہ، خزرج؛ بڑی شاخیں: عمرو، حارث، عوف۔","",{"v":600270,"im":["v6_p270.jpg"]}],[2846,"[تصویر: غزوہ احد کا نقشہ — جبل احد، جبل عینین (تیر اندازوں کی پہاڑی)، پیغمبر اسلام کا پڑاؤ، وادی اضم (الحمض)، وادی قناۃ]\nنقشے کی علامات: خالد بن ولید کی قیادت میں گھڑ سوار مشرکین کا دھاوا؛ خالد بن ولید کے صحابہ کرام رضی اللہ عنہم اور رسول اللہ صلی اللہ علیہ وسلم پر حملے؛ مجاہدین کا قیادت کے گرد اجتماع اور بھرپور مقابلہ؛ مجاہدین کا مدینہ کی طرف جانا اور پھر قیادت کی طرف پلٹنا؛ کفار کے رسول اللہ صلی اللہ علیہ وسلم پر جان لیوا حملے؛ مسلمانوں کی دامن کوہ میں پناہ گزینی؛ کفار کی حتمی پسپائی۔\nمیں سے کسی ایک میں بھی زندگی کی رمق باقی بچی تو اپنے رب کے حضور ہمارا کیا عذر ہوگا؟ خارجہ رضی اللہ عنہ بولے: رب ذوالجلال کے حضور ہمارا کوئی عذر نہیں ہوگا۔ یہ کہہ کر وہ تینوں میدان کارزار میں کود پڑے۔ سفیان بن عبد شمس سلمی نے سیدنا عباس بن عبادہ رضی اللہ عنہ کو شہید کر دیا اور سیدنا خارجہ رضی اللہ عنہ کو صفوان بن امیہ نے شہید کر ڈالا۔ اسی طرح اوس بن ارقم رضی اللہ عنہ بھی مشرکوں سے لڑتے لڑتے شہید ہو گئے۔(1)\n§لشکر اسلام احد کی پناہ گاہ میں\nجب مسلمانوں کو پتہ چلا کہ رسول اللہ صلی اللہ علیہ وسلم سلامت ہیں اور آپ کے قتل کی خبر محض افواہ ہے تو اس موقع پر آپ صلی اللہ علیہ وسلم کی آواز مبارک پہچان کر مشرکین بھی بھانپ گئے کہ آپ یہیں موجود ہیں، چنانچہ وہ پوری قوت سے آپ صلی اللہ علیہ وسلم پر حملہ کرنے کے لیے چڑھ دوڑے۔ رسول اللہ صلی اللہ علیہ وسلم کی ثابت قدمی اور آپ کے مخلص صحابہ کی سرفروشی نے مشرکین کی تمام تدبیروں کو ملیا میٹ کر دیا۔ یوں مسلمانوں کو دوبارہ منظم ہونے اور رسول اللہ صلی اللہ علیہ وسلم کے گرد جمع ہونے کا موقع مل گیا۔ جب رسول اللہ صلی اللہ علیہ وسلم کے پاس مسلمانوں کی ایک جماعت اکٹھی ہو گئی تو آپ صلی اللہ علیہ وسلم نے مجاہدین کو دوبارہ گھیراؤ","",{"v":600271,"fn":"(1) المغازي للواقدي: 227,228/1، إمتاع الأسماع: 159/1","im":["v6_p271.jpg"]}],[2847,"[تصویر: جبل احد کا سنگلاخ نشیبی حصہ]\nکے خطرے اور مزید نقصان سے بچانے کے لیے جبل احد کے محفوظ مقامات کی طرف لے جانے کا ارادہ فرمایا۔ جس بات کی وجہ سے کسی قابل ذکر نقصان کے بغیر مسلمانوں کو آسانی کے ساتھ پہاڑ کے محفوظ مقامات کی جانب پلٹنے میں مدد ملی، وہ یہ ہے کہ بہت سے مشرکین نے رسول اللہ صلی اللہ علیہ وسلم کے قتل کی افواہ کو سچ جانا جس کا اعلان ابن قمیہ نے کیا تھا۔ ابن قمیہ نے سیدنا مصعب بن عمیر رضی اللہ عنہ کو شہید کیا تھا اور چونکہ ان کی شکل رسول اللہ صلی اللہ علیہ وسلم سے ملتی جلتی تھی، اس لیے وہ اپنے زعم باطل میں رسول اللہ صلی اللہ علیہ وسلم کو قتل کر چکا تھا اور اس نے صاف اعلان کر دیا تھا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو قتل کر دیا ہے، چنانچہ مشرکین میں سے بہت سے لوگ جنگ سے اس لیے رک گئے کہ اب مسلمانوں کو شکست ہو چکی ہے اور اب وہ کھڑے نہیں ہو سکیں گے۔ بعض مشرکین آرام کرنے لگے اور بعض مسلمان مقتولین کا مثلہ کرنے میں مشغول ہو گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے اس موقع کو غنیمت جانا اور اپنے صحابہ کو ساتھ لے کر پہاڑ کی طرف جانے میں عجلت کا اہتمام فرمایا۔\nآپ پہاڑ کی طرف ایک تنظیم کے ساتھ جا رہے تھے۔ یہ ایک زبردست تدبیر اور مسلمانوں کی حفاظت کا اہم ترین عمل تھا۔ پلٹنے کے اس عمل میں شکستگی یا افسردگی کے آثار نہیں تھے۔ نہ مسلمان اپنے حوصلے ہار کر پسپا ہو رہے تھے نہ میدان جنگ سے بھاگ رہے تھے بلکہ یہ ان کے شفیق سالار اعظم رسول اللہ صلی اللہ علیہ وسلم کے حکم کی تعمیل تھی تا کہ مسلمان","",{"v":600272,"im":["v6_p272.jpg"]}],[2848,"اپنے ولولوں اور حوصلوں کو از سر نو یکجا کر کے مشرکین کے ارادوں کو ناکام بنا سکیں۔ رسول اللہ صلی اللہ علیہ وسلم جب پہاڑ کی طرف بڑھنے لگے تو مشرکین نے آپ صلی اللہ علیہ وسلم کا تعاقب کیا اور تیزی سے حملے شروع کر دیے۔\n§حملہ آور عثمان بن عبد اللہ کا قتل\nجب مسلمان پہاڑ کی طرف بڑھ رہے تھے تو مشرکین کا ایک ماہر شہسوار عثمان بن عبد اللہ بن مغیرہ بڑی تیزی سے رسول اللہ صلی اللہ علیہ وسلم کے تعاقب میں آیا۔ وہ آپ صلی اللہ علیہ وسلم کو قتل کرنا چاہتا تھا۔ اس نے اپنے گھوڑے کو سرپٹ دوڑایا۔ وہ کہہ رہا تھا کہ اگر محمد (صلی اللہ علیہ وسلم) بچ گئے تو میں ناکام ہو گیا۔ رسول اللہ صلی اللہ علیہ وسلم فوراً اس کا مقابلہ کرنے کے لیے تیار ہو گئے۔ لیکن عثمان بن عبد اللہ بن مغیرہ کے گھوڑے کو ٹھوکر لگی اور وہ ایک گڑھے میں گر گیا۔ اس دوران رسول اللہ صلی اللہ علیہ وسلم کے ایک محافظ حارث بن صمہ رضی اللہ عنہ اس کے مقابلے کے لیے لپکے۔ انھوں نے عثمان بن عبد اللہ کو اپاہج کر دیا۔ پھر اس کی گردن کاٹ کر اسے واصل جہنم کیا۔ بعد ازاں سیدنا حارث رضی اللہ عنہ اس کے سارے ہتھیار اٹھا لائے اور رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں پیش کر دیے تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n«الْحَمْدُ لِلَّهِ الَّذِي أَحَانَهُ»\n’’اس اللہ کا شکر ہے جس نے اسے ہلاک کیا ہے۔‘‘(1)\n§عبید بن حاجز عامری کی ہلاکت\nعثمان بن عبد اللہ کے قتل کے بعد مشرکین بہت مشتعل ہو گئے۔ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کا تعاقب کیا اور آپ کو قتل کرنے کی کوشش میں پورا زور لگا دیا۔ اس اثنا میں کہ آپ ابھی وادی ہی میں تھے، عبید بن حاجز عامری نے سیدنا حارث بن صمہ رضی اللہ عنہ پر حملہ کیا اور ان کے کندھے پر ایک کاری ضرب لگائی جس سے ان کا کندھا شدید زخمی ہو گیا۔ مسلمان فوراً ان کی مدد کو پہنچے۔ سیدنا ابو دجانہ رضی اللہ عنہ نے عبید بن حاجز پر حملہ کیا اور اسے تلوار کے ایک ہی بھرپور وار سے جہنم رسید کر دیا۔(2)\n§صرف ابی بن خلف نبی صلی اللہ علیہ وسلم کے ہاتھوں قتل ہوا\nہجرت سے پہلے جب رسول اللہ صلی اللہ علیہ وسلم مکہ میں تھے تو ابی بن خلف رسول اللہ صلی اللہ علیہ وسلم سے کہا کرتا تھا:\n«إِنَّ عِنْدِي فَرَسًا أَعْلِفُهَا كُلَّ يَوْمٍ فَرْقَ ذُرَّةٍ لَعَلِّي أَقْتُلُكَ عَلَيْهَا»","",{"v":600273,"fn":"(1) إمتاع الأسماع: 155,156/1، سبل الهدى والرشاد: 209/4\n(2) إمتاع الأسماع: 156/1، السيرة الحلبية: 518/2، سبل الهدى والرشاد: 209/4"}],[2849,"’’(اے محمد!) میرے پاس (العوذ نامی) گھوڑا ہے۔ اسے میں روزانہ ایک فرق (تقریباً ساڑھے سات کلو) مکئی کھلاتا ہوں تا کہ میں اس پر سوار ہو کر تمھیں قتل کروں۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم جواباً فرماتے تھے:\n«بَلْ أَنَا أَقْتُلُكَ، إِنْ شَاءَ اللهُ»\n’’(نہیں نہیں) بلکہ ان شاء اللہ میں ہی تجھے قتل کروں گا۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم کا یہ فرمان پورا کرنے کے لیے تقدیر ابی بن خلف کو احد کے میدان میں کھینچ لائی۔ جب مسلمان مجاہدین نے پہاڑ کی طرف رخ پھیرا تو ابی بن خلف اپنے العوذ نامی گھوڑے پر سوار ہو کر دندناتا ہوا آپہنچا۔ اللہ کا یہ دشمن رسول اللہ صلی اللہ علیہ وسلم کو قتل کرنے پر تلا ہوا تھا۔ وہ کہنے لگا: اے محمد! اگر آج تم نجات پا گئے تو پھر میں ناکام و نامراد ہو گیا۔ یہ سن کر مجاہدین نے عرض کی: اے اللہ کے رسول! کیا ہم میں سے کوئی آدمی پیچھے مڑ کر اس بدبخت کا مقابلہ نہ کرے؟ آپ صلی اللہ علیہ وسلم نے فرمایا:\n«اسْتَأْخِرُوا اسْتَأْخِرُوا»\n’’نہیں نہیں! اسے چھوڑ دو، اسے مہلت دو۔‘‘\nجب وہ قریب آپہنچا تو رسول اللہ صلی اللہ علیہ وسلم نے سیدنا حارث بن صمہ رضی اللہ عنہ سے ان کا نیزہ لیا اور بنفس نفیس ابی بن خلف کے سامنے جا کھڑے ہوئے۔ ابی بن خلف لوہے میں غرق تھا لیکن خود اور زرہ کے درمیان حلق کے پاس تھوڑی سی جگہ کھلی دکھائی دے رہی تھی۔ آپ صلی اللہ علیہ وسلم نے اس خالی جگہ کا نشانہ باندھا اور اس پر نیزہ دے مارا۔ نیزے کی خراش لگتے ہی وہ اس قدر بدحواس ہو گیا کہ اپنے گھوڑے ہی پر دائیں بائیں لڑکھنے لگا۔ پھر وہ دم دبا کر اپنے ہم نواؤں کی طرف بھاگ گیا۔ وہاں پہنچ کر خوف کے مارے اس کا خون منجمد ہو گیا، حالانکہ اس کی گردن پر نیزے سے اتنا ہلکا زخم آیا تھا کہ خون کی ایک بوند بھی نہیں چپکی تھی۔ وہ یہ خراش بھی نہ سہہ سکا۔ تڑپ تڑپ کر چیخنے لگا:\n«قَتَلَنِي وَاللهِ مُحَمَّدٌ»\n’’اللہ کی قسم! مجھے محمد (صلی اللہ علیہ وسلم) نے قتل کر ڈالا ہے۔‘‘\nاس کے ساتھیوں نے اسے دلاسہ دیا کہ اللہ کی قسم! تمھیں کوئی بڑا زخم نہیں آیا، دل چھوٹا نہ کرو۔ ابی بن خلف کہنے لگا: محمد نے مجھ سے مکہ میں کہا تھا:\n«أَنَا أَقْتُلُكَ، فَوَاللهِ! لَوْ بَصَقَ عَلَيَّ لَقَتَلَنِي»","",{"v":600274}],[2850,"’’میں تمھیں قتل کر دوں گا۔ اس لیے اللہ کی قسم! اگر محمد (صلی اللہ علیہ وسلم) مجھ پر تھوک بھی دیتے تو میری جان نکل جاتی۔‘‘\nسیدنا عروہ سے روایت ہے کہ وہ بیل کی طرح ڈکرا ڈکرا کر چیختا تھا اور کہتا تھا: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! جو اذیت مجھے پہنچ رہی ہے، اگر وہ ذی المجاز کے سارے باشندوں میں تقسیم کی جاتی تو وہ سب مر جاتے۔ بالآخر قریشی لشکر جب مکہ سے چھ میل کے فاصلے پر مقام سرف تک پہنچا تو یہ بدبخت وہیں چلاتے چلاتے مر گیا۔(1)\n§طلحہ رضی اللہ عنہ نے جنت واجب کر لی\nرسول اللہ صلی اللہ علیہ وسلم جب پہاڑ کی طرف جا رہے تھے تو رستے میں چٹان آ گئی۔ رسول اللہ صلی اللہ علیہ وسلم نے جب اس پر چڑھنے کی کوشش کی تو نہ چڑھ سکے کیونکہ آپ نے اوپر تلے دو زرہیں پہن رکھی تھیں۔ ان کے بوجھ سے آپ کا بدن بھاری ہو گیا تھا۔ مزید برآں آپ شدید زخمی بھی تھے۔ اس موقع پر سیدنا طلحہ بن عبید اللہ رضی اللہ عنہ نیچے بیٹھ گئے اور آپ صلی اللہ علیہ وسلم کو کندھوں پر اٹھا کر کھڑے ہو گئے۔ اس طرح آپ صلی اللہ علیہ وسلم چٹان پر پہنچ گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n«أَوْجَبَ طَلْحَةُ»\n’’طلحہ نے (اپنے لیے جنت) واجب کر لی ہے۔‘‘(2)\nاس جلیل الشان عمل کے دوران جس کا ثواب سیدنا طلحہ رضی اللہ عنہ کو جنت کی صورت میں ملا، ان کا نبی صلی اللہ علیہ وسلم کو اٹھانا ان کے لیے زبردست خیر و برکت کا باعث بن گیا، یعنی اس طرح طلحہ رضی اللہ عنہ کی ایک ٹانگ کا لنگڑا پن بھی ختم ہو گیا، قبل ازیں جب وہ رسول اللہ صلی اللہ علیہ وسلم کا دفاع کر رہے تھے تو زخموں کی شدت کے باعث ان کی ٹانگ لنگڑاہٹ کا شکار ہو گئی تھی۔\nسیدنا طلحہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم کو اٹھایا تو نہایت صبر اور مشقت کے ساتھ اپنی چال کو ہموار رکھا۔ انھیں خدشہ تھا کہ میری لنگڑی ٹانگ ادھر ادھر جھول گئی تو اس طرح جناب رسالت مآب صلی اللہ علیہ وسلم کی ذات گرامی کے گر جانے اور نتیجتاً نقصان پہنچنے کا امکان ہے، چنانچہ وہ تکلف ہموار قدموں سے چلتے رہے۔ اس طرح دشواری سے چلتے چلتے ان کی ٹانگ طبعی حالت پر آ گئی۔ یوں ان کا لنگڑا پن خود بخود ٹھیک ہو گیا۔(3)\n§مشرکین کی آخری یلغار\nجب رسول اللہ صلی اللہ علیہ وسلم پہاڑ کی گھائی میں پہنچ کر تشریف فرما ہو گئے تو مشرکین نے رسول اللہ صلی اللہ علیہ وسلم پر آخری بھرپور وار","",{"v":600275,"fn":"(1) فتح الباري لابن رجب: 732/2، السيرة لابن إسحاق: 339,340/1، السيرة لابن هشام: 89/3، الطبقات لابن سعد: 46/2، زاد المعاد: 209,210/3\n(2) السيرة لابن هشام: 91,92/3\n(3) موسوعة الغزوات الكبرى لباشميل: 275/1"}],[2851,"کرنے کا فیصلہ کیا۔\nابن اسحاق کا بیان ہے کہ جس وقت رسول اللہ صلی اللہ علیہ وسلم گھائی کے اندر تشریف فرما تھے، ابوسفیان اور خالد بن ولید کی قیادت میں مشرکین کا ایک جنگجو دستہ پہاڑ پر چڑھ آیا۔ رسول اللہ صلی اللہ علیہ وسلم نے دعا فرمائی:\n«اللَّهُمَّ! إِنَّهُ لَا يَنْبَغِي لَهُمْ أَنْ يَعْلُونَا»\n’’اے اللہ! یہ اوپر ہم تک نہ چڑھنے پائیں۔‘‘\nاس موقع پر سیدنا عمر بن خطاب رضی اللہ عنہ اور آپ صلی اللہ علیہ وسلم کے دیگر جانباز مہاجرین صحابہ رضی اللہ عنہم نے ان سے زبردست مقابلہ کیا اور انھیں پسپا ہونے پر مجبور کر دیا۔(1)\nاموی کا بیان ہے کہ مشرکین پہاڑ پر چڑھ آئے تو رسول اللہ صلی اللہ علیہ وسلم نے سیدنا سعد رضی اللہ عنہ سے فرمایا:\n«أَجْنِبْهُمْ» يَقُولُ: «أَرْدُوهُمْ»\n’’ان کے حوصلے توڑ دو اور انھیں نا امید کر کے پسپا کر دو۔‘‘\nسیدنا سعد رضی اللہ عنہ عرض کرنے لگے: میں اکیلا کیسے ان کے حوصلے پست کر سکوں گا؟ رسول اللہ صلی اللہ علیہ وسلم نے انھیں پھر وہی حکم دیا۔ آپ صلی اللہ علیہ وسلم نے تین بار اپنا ارشاد دہرایا۔ بالآخر سیدنا سعد رضی اللہ عنہ نے اپنے ترکش سے ایک تیر نکالا، پھر ایک مشرک کا نشانہ لے کر تیر مارا تو وہ ڈھیر ہو گیا۔ سیدنا سعد رضی اللہ عنہ کہتے ہیں: میں نے پھر وہی تیر لیا۔ میں اس تیر کو خوب پہچانتا تھا۔ اس سے دوسرے مشرک کو مارا، وہ بھی ہلاک ہو گیا۔ اس کے بعد میں نے پھر وہی تیر لیا۔ اس سے تیسرے مشرک کو مارا تو وہ بھی دم توڑ گیا۔ یہ صورت حال دیکھ کر مشرکین نیچے اتر گئے، پھر انھوں نے پہاڑ کا رخ نہیں کیا۔ میں نے کہا کہ یہ مبارک تیر ہے، پھر میں نے اسے اپنے ترکش میں سنبھال کر رکھ لیا۔ یہ تیر زندگی بھر سیدنا سعد رضی اللہ عنہ کے پاس رہا اور ان کے بعد ان کی اولاد کے حصے میں آیا۔(2)\n§پہاڑ کی گھائی پر کنٹرول روم کا قیام\nرسول اللہ صلی اللہ علیہ وسلم نے مجاہدین اسلام کو نہایت منظم طریقے سے بچا کر پہاڑ کا درہ عبور کیا۔ رستے میں کئی جھڑپیں ہوئیں لیکن ان تمام جھڑپوں میں مسلمان کامیاب رہے۔ رسول اللہ صلی اللہ علیہ وسلم اور آپ کے مخصوص ساتھیوں نے مشرکین کے سواروں پر غلبہ پایا۔ رسول اللہ صلی اللہ علیہ وسلم جبل احد کی پہاڑیوں میں سے ایک بلند ترین پہاڑی پر پہنچ گئے۔ وہاں","",{"v":600276,"fn":"(1) السيرة لابن إسحاق: 340,341/1، السيرة لابن هشام: 91/3، البداية والنهاية: 25/4\n(2) زاد المعاد: 205/3، سبل الهدى والرشاد: 211/4"}],[2852,"[تصویر: جبل احد میں رسول اللہ صلی اللہ علیہ وسلم سے منسوب گھائی کا ایک منظر]\nآپ صلی اللہ علیہ وسلم نے از سر نو نہایت مضبوط دفاعی اسکیم بنائی۔ اس اسکیم کے تحت مجاہدین نے مشرکوں کے وہ سارے حربے بے کار کر دیے جو انھوں نے مسلمانوں کی تباہی کے لیے اختیار کیے تھے۔\nرسول اللہ صلی اللہ علیہ وسلم کی اس کامیاب ترین حکمت عملی سے مسلمانوں کو بڑی تقویت ملی۔ ان کے زخم خوردہ حوصلوں اور ولولوں میں ایک نئی جان پڑ گئی۔ تیر اندازوں کی غلطی سے مجاہدین اسلام جس ہلاکت بار فضا میں گھر گئے تھے، اب وہ اس سے باہر نکل آئے اور مشرکوں پر نئے سرے سے حملہ کرنے کے قابل ہو گئے۔\nرسول اللہ صلی اللہ علیہ وسلم نے احد کے ایک اونچے پہاڑ کے دہانے کو منتخب فرما کر وہاں مضبوط ہیڈ کوارٹر بنا لیا، اس پہاڑی درے کو بہت سی پہاڑیوں نے گھیر رکھا تھا۔ یہ درہ ایک مضبوط قلعہ بن گیا۔ مجاہدین یہاں پہنچ کر بالکل محفوظ ہو گئے۔ مشرکین پر دوبارہ مایوسی کا چھینٹا پڑ گیا اور وہ نامراد ہو کر پلٹ گئے۔\nجب رسول اللہ صلی اللہ علیہ وسلم پہاڑ پر پہنچ گئے تو ادھر ادھر جانے والے مسلمان آپ کے پاس جمع ہونے لگے۔ اس طرح مسلمانوں کی حالت بہتر ہو گئی اور ان کی قوت میں اضافہ ہونے لگا۔ رسول اللہ صلی اللہ علیہ وسلم پہاڑ کی ایسی جگہ پر قلعہ بند ہوئے جہاں مشرکین کا پہنچنا محال تھا۔ جونہی مشرکین ادھر کا رخ کرتے، مسلمانوں کے تیر انھیں ہلاک کر دیتے تھے جیسا کہ سیدنا سعد رضی اللہ عنہ کے تیر نے مشرکین کو ہلاک کیا تھا۔ مجاہدین اپنی قیادت کی سرپرستی میں اس جگہ بالکل محفوظ تھے۔ یہاں سے مشرکین صاف نظر آ رہے تھے۔(1)","",{"v":600277,"fn":"(1) موسوعة الغزوات الكبرى لباشميل: 276/1","im":["v6_p277.jpg"]}],[2853,"§اللہ تعالیٰ نے ثابت قدم رہنے والوں پر سکینت طاری کر دی\nہر چند احد کے روز مسلمانوں کو کڑی آزمائش کا سامنا کرنا پڑا۔ تاہم اللہ تعالیٰ نے بڑا کرم فرمایا۔ صحابہ کرام رضی اللہ عنہم کو اطمینان و سکون سے نوازا اور اس وحشت ناک ماحول میں مسلمانوں کے دلوں پر سکینت طاری کر دی، اس بارے میں خود اللہ رب العزت کا ارشاد عالی ہے:\n﴿ثُمَّ أَنْزَلَ عَلَيْكُمْ مِنْ بَعْدِ الْغَمِّ أَمَنَةً نُّعَاسًا يَغْشَىٰ طَائِفَةً مِنْكُمْ وَطَائِفَةٌ قَدْ أَهَمَّتْهُمْ أَنْفُسُهُمْ يَظُنُّونَ بِاللهِ غَيْرَ الْحَقِّ ظَنَّ الْجَاهِلِيَّةِ﴾\n’’پھر اس نے غم کے بعد تم پر سکون نازل کیا جس سے تمھارے ایک گروہ پر اونگھ طاری ہو گئی اور دوسرے گروہ کو اپنی جان کی فکر پڑ گئی۔ یہ اللہ کے بارے میں خلاف حقیقت زمانہ جاہلیت جیسی بدگمانیوں میں مبتلا رہے۔‘‘(1)\nسیدنا ابو طلحہ رضی اللہ عنہ بیان کرتے ہیں کہ میں ان لوگوں میں سے تھا جن پر احد کے روز اونگھ چھا گئی تھی یہاں تک کہ میری تلوار رہ رہ کر میرے ہاتھوں سے گر جاتی تھی اور میں اسے بار بار تھامتا تھا۔(2)\nامام اسحاق بن راہویہ سیدنا زبیر بن عوام رضی اللہ عنہ سے بیان کرتے ہیں۔ انھوں نے فرمایا: اللہ کی قسم! اونگھ نے مجھ پر غلبہ پا لیا اور ایک روایت میں ہے: جب ہم احد کے روز رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے اور ہمیں خوف نے گھیرے میں لے رکھا تھا، عین اس وقت ہم پر نیند مسلط کر دی گئی۔ ہم میں سے ہر شخص کی ٹھوڑی اس کے سینے سے لگ گئی تھی۔ اللہ کی قسم! میں اسی عالم غنودگی میں معتب بن قشیر کا یہ جملہ سن رہا تھا:\n«لَوْ كَانَ لَنَا مِنَ الْأَمْرِ شَيْءٌ مَّا قُتِلْنَا هَاهُنَا»\nمیں نے یہ بات یاد رکھی یہاں تک کہ اللہ تعالیٰ نے یہ آیت کریمہ نازل فرما دی:\n﴿يَقُولُونَ لَوْ كَانَ لَنَا مِنَ الْأَمْرِ شَيْءٌ مَّا قُتِلْنَا هَاهُنَا﴾ (آل عمران 3:154)\n’’وہ کہتے ہیں کہ اگر اس معاملے میں ہمارا کچھ بھی اختیار ہوتا تو ہم یہاں نہ مارے جاتے۔‘‘(3)\n§فرشتے محافظ بن گئے\nصحیح روایات سے ثابت ہے کہ غزوہ احد میں اللہ تعالیٰ نے جبریل اور میکائیل علیہما السلام کو بھیجا تا کہ رسول اللہ صلی اللہ علیہ وسلم کا","",{"v":600278,"fn":"(1) آل عمران 3:154\n(2) صحيح البخاري: 4068\n(3) المطالب العالية لابن حجر: 219/4، المعجم الكبير للطبراني: 166/3"}],[2854,"دفاع کرنے کے لیے وہ دونوں جنگ کریں، اس لیے کہ اللہ تعالیٰ نے ہر خطرے کی طرف سے آپ صلی اللہ علیہ وسلم کی حفاظت کی ذمہ داری خود قبول فرمائی تھی۔ اللہ تعالیٰ کا فرمان ہے:\n﴿وَاللهُ يَعْصِمُكَ مِنَ النَّاسِ﴾\n’’اور اللہ آپ کو لوگوں سے بچا لے گا۔‘‘(1)\nسیدنا سعد بن ابی وقاص رضی اللہ عنہ سے مروی حدیث میں ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو احد کے دن دیکھا کہ دو آدمی آپ کی طرف سے زبردست دفاعی جنگ کر رہے تھے، وہ سفید کپڑوں میں ملبوس تھے، ان دونوں کو میں نے کبھی پہلے دیکھا نہ بعد میں۔(2)\nامام بیہقی نے عروہ رضی اللہ عنہ کا اس آیت: ﴿وَلَقَدْ صَدَقَكُمُ اللهُ وَعْدَهُ إِذْ تَحُسُّونَهُمْ بِإِذْنِهِ﴾ (آل عمران 3:152) کے بارے میں ایک قول نقل کیا ہے کہ اللہ تبارک و تعالیٰ نے صبر اور تقویٰ کی بدولت مسلمانوں سے پانچ ہزار فرشتوں کے ذریعے سے مدد کا وعدہ فرمایا تھا۔ اللہ نے وہ وعدہ پورا فرمایا لیکن جب مسلمانوں نے رسول اللہ صلی اللہ علیہ وسلم کے فرمان کی خلاف ورزی کرتے ہوئے اپنا مورچہ چھوڑ دیا اور دنیاوی مال کے پیچھے بھاگے تو اللہ تعالیٰ نے فرشتوں کی مدد اٹھائی۔\nامام بیہقی، مجاہد رحمہ اللہ کے قول کی وضاحت کرتے ہوئے کہتے ہیں کہ امام مجاہد رحمہ اللہ نے جو یہ فرمایا ہے: فرشتوں نے بدر کے دن کے علاوہ لڑائی نہیں کی تو اس کا مطلب یہ ہے کہ جب قوم نے رسول اللہ صلی اللہ علیہ وسلم کی نافرمانی کی اور رسول اللہ صلی اللہ علیہ وسلم کے حکم کے مطابق صبر نہیں کیا تو پھر فرشتوں نے بھی لڑائی نہیں کی۔(3)\nامام طبرانی رحمہ اللہ محمود بن لبید کے طریق سے بیان کرتے ہیں کہ حارث بن صمہ رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے احد کے دن مجھ سے عبدالرحمن بن عوف رضی اللہ عنہ کے متعلق پوچھا کہ وہ کہاں ہیں؟ اس وقت آپ صلی اللہ علیہ وسلم گھائی میں تھے۔ میں نے رسول اللہ صلی اللہ علیہ وسلم سے عرض کیا کہ میں نے انھیں پہاڑ کے دامن میں دیکھا ہے تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n«أَمَا إِنَّ الْمَلَائِكَةَ تُقَاتِلُ مَعَهُ»\n’’بلاشبہ فرشتے ان کے ساتھ مل کر جنگ کر رہے ہیں۔‘‘\nحارث رضی اللہ عنہ کہتے ہیں کہ بعد ازاں میں عبدالرحمن بن عوف رضی اللہ عنہ کے پاس پہنچا تو میں نے ان کے سامنے سات","",{"v":600279,"fn":"(1) المائدة 5:67\n(2) صحيح البخاري: 4054، صحيح مسلم: 2306\n(3) دلائل النبوة للبيهقي: 255,256/3، سبل الهدى والرشاد: 206/4"}],[2855,"مقتولوں کی لاشیں پائیں۔ میں نے انھیں دعا دی: اللہ تعالیٰ آپ کو ظفر مند رکھے۔ پھر پوچھا: کیا آپ ہی نے ان سب کو قتل کیا ہے؟ عبدالرحمن بن عوف رضی اللہ عنہ کہنے لگے: نہیں، اسے اور اس دوسرے شخص کو تو میں نے مارا ہے، البتہ ان دیگر لوگوں کو جنھوں نے قتل کیا ہے، انھیں میں نے نہیں دیکھا۔ حارث رضی اللہ عنہ فرماتے ہیں کہ جب میں نے سیدنا عبدالرحمن بن عوف رضی اللہ عنہ کی یہ بات سنی تو میں بے ساختہ پکار اٹھا: بلاشبہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم نے سچ فرمایا ہے۔(1)\nابن اسحاق، ابن عساکر اور بیہقی عبداللہ بن عون سے، وہ عمیر بن اسحاق سے روایت کرتے ہیں کہ جب احد کے روز رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کوئی بھی موجود نہ رہا، اس وقت سیدنا سعد بن ابی وقاص رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کے سامنے تیر چلا رہے تھے، وہاں ایک نوجوان بھی موجود تھا، وہ سیدنا سعد رضی اللہ عنہ کو تیر پکڑاتا جاتا تھا، وہ تیر جہاں بھی جاتا تھا، وہ نوجوان وہی تیر پھر پیش کر دیتا تھا اور کہتا تھا: اے ابو اسحاق! اسے چلاؤ۔ جب ہم نے جنگ سے فراغت پائی تو ہم اس نوجوان کو ڈھونڈنے لگے لیکن وہ نوجوان کہیں نہیں ملا، نہ اس کا کوئی اتا پتا معلوم ہو سکا۔(2)\n§جنگ کا خاتمہ\nابوسفیان نے آخری مرتبہ فیصلہ کن حملے کی کوشش کی لیکن وہ خائب و خاسر رہا اور مایوس ہو گیا، دیگر قائدین قریش بھی مایوس ہو گئے۔ انھیں یقین ہو گیا کہ مسلمانوں کے دوبارہ منظم ہو جانے اور رسول اللہ صلی اللہ علیہ وسلم کے گرد محفوظ پناہ گاہ میں جمع ہو جانے کے بعد اب ان سے از سر نو مقابلہ کرنا ممکن نہیں۔ اس پر مستزاد یہ کہ مکی لشکر کے لوگ بری طرح تھک چکے تھے۔ اس کے علاوہ انھیں جنگ کے پہلے مرحلے میں مسلمانوں کے ہاتھوں ناقابل تلافی نقصان اٹھانا پڑا تھا جس کی بنا پر مکی فوج کے دلوں میں مسلمانوں کا دبدبہ بیٹھ گیا تھا کیونکہ مسلمانوں نے مکی لشکر کے علمبرداروں کا صفایا کر دیا تھا اور مشرکین کو شکست دے کر بھگا دیا تھا۔ یوں قائدین قریش مسلمانوں کو مزید نقصان پہنچانے کی سکت سے محروم اور مایوس ہو گئے۔ ابوسفیان نے جنگ ختم کر کے کوچ کرنے کا حکم دے دیا۔ اس طرح جنگ ختم ہو گئی اور احد کے علاقے میں فوجی کارروائیاں بند ہو گئیں۔(3)\n§شہدائے عظام کی لاشوں سے بہیمانہ سلوک\nخاتمہ جنگ کے فیصلے کے بعد مشرکین کوچ کی تیاری میں مصروف ہو گئے اور اپنے مقتولین کی تلاش میں میدان کارزار جا پہنچے۔ اسی دوران قریش کا ایک گروہ اپنی پستی کی انتہا پر اتر آیا اور اپنے کینے اور بغض کی آگ بجھانے کے لیے","",{"v":600280,"fn":"(1) المعجم الكبير للطبراني: 271/3\n(2) دلائل النبوة للبيهقي: 257/3، سبل الهدى والرشاد: 206/4\n(3) موسوعة الغزوات الكبرى لباشميل: 277,278/1"}],[2856,"مسلمان شہداء کا مثلہ کرنے لگا۔ انھوں نے مسلمانوں کے پیٹ پھاڑ دیے۔ ان کی انتڑیاں باہر نکال دیں۔ ناک اور کان کاٹ ڈالے یہاں تک کہ بعض نے شہداء کے حساس اعضاء بھی کاٹ دیے۔(1)\n§سید الشہداء کے جسد بے روح کی توہین\nسیدنا حمزہ رضی اللہ عنہ تمام شہداء سے بڑھ کر وحشت و شیطنت اور انتقامی کارروائی کا نشانہ بنے۔ سرداران قریش سب سے زیادہ آپ ہی کی ذات گرامی سے بدلہ لینے پر ادھار کھائے بیٹھے تھے۔ سیدنا حمزہ رضی اللہ عنہ نے بدر کے روز سیدنا علی رضی اللہ عنہ سے مل کر سرداران قریش کے دو سرداروں عتبہ بن ربیعہ اور شیبہ بن ربیعہ اور ہند بنت عتبہ کے بھائی ولید بن عتبہ کو جہنم رسید کیا تھا۔ یہ سب بنو امیہ بن عبد شمس بن عبد مناف سے تعلق رکھتے تھے۔ اسی لیے ہند بنت عتبہ تمام مشرکین سے بڑھ کر زہر کی پوٹلی بنی ہوئی تھی اور سیدنا حمزہ رضی اللہ عنہ سے بڑا خار کھائے بیٹھی تھی۔ اسی وجہ سے وہ اپنے خاوند اور مشرکین کے سالار ابوسفیان کے ساتھ مشرکین کو مسلمانوں کے خلاف حملے کرنے کی ترغیب دینے آئی تھی۔\n[تصویر: مسجد سیدنا حمزہ رضی اللہ عنہ]","",{"v":600281,"fn":"(1) سمط النجوم العوالي: 284/1، موسوعة الغزوات الكبرى لباشميل: 270/1 و 278","im":["v6_p281.jpg"]}],[2857,"خاص طور پر وہ وحشی کی بڑی حوصلہ افزائی کرتی تھی۔\nادھر جنگ ختم ہوئی، اُدھر وحشی ہند بنت عتبہ کے پاس پہنچا اور کہنے لگا: اگر میں آپ کے باپ کے قاتل کو قتل کر دوں تو مجھے کیا ملے گا؟ وہ کہنے لگی کہ میں تمھیں اپنے قیمتی ملبوسات دوں گی۔ وحشی نے اسے یقین دلایا کہ میں نے سیدنا حمزہ رضی اللہ عنہ کو قتل کر دیا ہے، چنانچہ ہند بنت عتبہ نے اسے اپنے زیورات اور کپڑے دے دیے اور وعدہ کیا کہ جب وہ مکہ واپس پہنچے گی تو اسے دس دینار بھی دے گی۔ اس کے بعد وحشی ہند بنت عتبہ کو اس جگہ لے گیا جہاں اس نے حمزہ رضی اللہ عنہ کو شہید کیا تھا۔ جب ہند نے سیدنا حمزہ رضی اللہ عنہ کی لاش دیکھی تو اسلام کے اس شیر دل فرزند کی لاش دیکھ کر تسکین و طمانیت سے سرشار ہو گئی۔(1)\nابن اسحاق کا بیان ہے کہ ہند بنت عتبہ اور اس کی دیگر کافر ساتھی عورتوں نے رسول اللہ صلی اللہ علیہ وسلم کے چچا حمزہ اور دیگر اصحاب کا مثلہ بھی کیا۔ ان ظالم عورتوں نے بہت سے صحابہ کرام رضی اللہ عنہم کے کان ناک کاٹ کاٹ کر اپنے لیے پازیب، ہار اور بالیاں بنائیں۔(2)\n§ہند بنت عتبہ کا وحشیانہ کلام\nمسلمانوں پر سرسری فتح نے کم ظرف مشرکین کو اس قدر اوچھا بنا دیا کہ انھوں نے اپنی درندگی کی داستانیں اشعار میں بیان کیں۔ ہند نے اپنی دشمنی کے اظہار کے لیے اشعار کہے۔ وہ ایک اونچی چٹان پر چڑھ گئی اور درج ذیل اشعار گا گا کر اپنے غم و غصے کا اظہار و اعلان کرنے لگی:\nنَحْنُ جَزَيْنَاكُمْ بِيَوْمِ بَدْرٍ وَالْحَرْبُ بَعْدَ الْحَرْبِ ذَاتُ سُعْرِ\nمَا كَانَ عَنْ عُتْبَةَ لِي مِنْ صَبْرٍ وَلَا أَخِي وَعَمِّهِ وَبِكْرِي\nشَفَيْتُ نَفْسِي وَقَضَيْتُ نَذْرِي شَفَيْتَ وَحْشِيُّ غَلِيلَ صَدْرِي\nفَشُكْرُ وَحْشِيٍّ عَلَيَّ عُمْرِي حَتَّى تَرِمَّ أَعْظُمِي فِي قَبْرِي\n’’ہم نے تم سے بدر کے دن کا بدلہ لے لیا ہے اور جنگ کے بعد پھر بھڑکنے والی جنگ ہو گی۔‘‘\n’’مجھے اپنے باپ عتبہ، اپنے بھائی (ولید)، چچا (شیبہ بن ربیعہ) اور بیٹے (حنظلہ) کی ہلاکت پر صبر نہ آتا تھا۔‘‘","",{"v":600282,"fn":"(1) السيرة لابن إسحاق: 342/1، السيرة لابن هشام: 96,97/3\n(2) السيرة النبوية لابن كثير، ص: 313، سبل الهدى والرشاد: 218/4"}],[2858,"اب میں نے اپنا دل ٹھنڈا کر لیا۔ میں نے اپنی نذر پوری کر لی۔ وحشی! تو نے میرے دل کی آگ بجھا دی ہے۔‘‘\n’’مجھ پر وحشی کا شکر و سپاس ہمیشہ واجب رہے گا۔ قبر میں میری ہڈیاں بھی بوسیدہ ہو جائیں گی، تب بھی میں اس کی شکر گزار رہوں گی۔‘‘\nاس کے جواب میں غزوہ بدر کے روز مسلمان ہونے والی مشہور قریشی شاعرہ سیدہ ہند بنت اثاثہ بن عباد بن مطلب بن عبد مناف رضی اللہ عنہا نے احد کے روز یہ اشعار کہے:\nخُزِيتِ فِي بَدْرٍ وَبَعْدَ بَدْرٍ يَا بِنْتَ وَقَّاعٍ عَظِيمِ الْكُفْرِ\nصَبَّحَكِ اللهُ غَدَاةَ الْفَجْرِ مِلْهَاشِمِيِّينَ الطُّوَالِ الزُّهْرِ\nبِكُلِّ قَطَّاعٍ حُسَامٍ يُفْرِي حَمْزَةُ لَيْثِي وَعَلِيٌّ صَقْرِي\nإِذَا رَامَ شَيْبٌ وَأَبُوكِ غَدْرِي فَخَضَّبَا مِنْهُ ضَوَاحِي النَّحْرِ\nوَنَذْرُكِ السُّوءُ فَشَرُّ نَذْرٍ\n’’اے عظیم کافر کی بیٹی! تو بدر کے دن بھی رسوا ہوئی اور بدر کے بعد بھی۔‘‘\n’’اللہ صبح سویرے ہی قد آور حسین ہاشمیوں کے ہاتھوں ہر کاٹنے والی تیز تلوار کے ذریعے سے تیرے غرور کا سفینہ ڈبو دے۔ سیدنا حمزہ تو میرے شیر ہیں اور سیدنا علی میرے شہباز ہیں۔‘‘\n’’جب تیرے چچا شیبہ اور تیرے باپ نے خیانت کا ارادہ کیا تو ان کے سینے خون سے رنگین ہو گئے۔‘‘\n’’تیری نذر پرلے درجے کی بدترین نذر ہے۔‘‘(1)\n§حمزہ رضی اللہ عنہ کی لاش سے ابوسفیان کا وحشیانہ سلوک\nابوسفیان جب فریقین کے مقتولین کا اندازہ لگا رہا تھا اور اپنے مقتولین ڈھونڈ رہا تھا، اس وقت اس کا گزر سیدنا حمزہ رضی اللہ عنہ کے قریب سے ہوا، ان کا مثلہ کیا جا چکا تھا۔ ابوسفیان بھی شدید اسلام دشمنی کی وجہ سے سیدنا حمزہ رضی اللہ عنہ سے گہری عداوت رکھتا تھا۔ اس وقت ابوسفیان نے انتہائی سنگ دلی کا مظاہرہ کرتے ہوئے اپنے نیزے کی نوک سیدنا حمزہ رضی اللہ عنہ کی باچھوں میں چبھو دی اور ان کی میت پر ضربیں لگانے لگا۔ وہ سیدنا حمزہ رضی اللہ عنہ کی لاش پر ضربیں بھی لگاتا جاتا تھا اور یہ بھی کہتا جاتا تھا: نافرمان! لے مزا چکھ!","",{"v":600283,"fn":"(1) السيرة لابن هشام: 97/3"}],[2859,"مقتولین کا مثلہ کرنا اور دشمنوں کا حلیہ بگاڑنا جاہلیت میں بھی معیوب سمجھا جاتا تھا۔ ابوسفیان کو احابیش کے سردار حلیس بن زبان حارثی نے سیدنا حمزہ رضی اللہ عنہ کی لاش پر ضربیں لگاتے دیکھا تو اُسے یہ بہیمانہ حرکت بڑی ناگوار گزری۔ وہ کہنے لگا: اے بنو کنانہ! ذرا اس قریش کے سردار ابوسفیان کو تو دیکھو، یہ سورما اپنے عم زاد سے اس حالت میں لڑ رہا ہے کہ وہ مارا جا چکا ہے، اب یہ بے چارہ تو مردہ اور بے جان ہے، بدلہ لینے کی سکت ہی نہیں رکھتا مگر یہ قریشی سورما ابوسفیان اُسے ابھی تک ضربیں لگا رہا ہے۔ یہ بات سُن کر ابوسفیان شرمندہ ہو گیا اور کہنے لگا: تجھ پر ہلاکت ہو، میری یہ حرکت کسی پر ظاہر نہ کر۔ بس مجھ سے ایک غلطی ہو گئی ہے۔(1)\n§ابوسفیان کی پکار\nقریب قریب سارے مکی لشکر کو یقین تھا کہ ابن قمیئہ کا دعویٰ سچا ہے اور نبی صلی اللہ علیہ وسلم یقیناً شہید ہو چکے ہیں لیکن مکی شاہسواروں کے آخری حملوں کے دوران دشمن اسلام ابوسفیان نے غور کیا کہ صحابہ کرام رضی اللہ عنہم پہاڑ کے ایک رُخ پر اکٹھے ہو رہے ہیں اور نہایت دلیری سے لڑ رہے ہیں۔ اسی بنا پر ابوسفیان کو ابن قمیئہ کے دعوے پر یقین نہیں آ رہا تھا، جب اس نے مکہ واپس جانے کی تیاری مکمل کر لی تو وہ پہاڑ پر چڑھا اور بلند آواز سے چلا چلا کر پوچھنے لگا:\nأَفِي الْقَوْمِ مُحَمَّدٌ؟\n’’کیا تم لوگوں میں محمد (صلی اللہ علیہ وسلم) زندہ موجود ہیں؟‘‘\nرسول اللہ صلی اللہ علیہ وسلم نے صحابہ کرام رضی اللہ عنہم کو ممانعت فرما دی کہ اس شخص کو کوئی جواب نہ دے۔ ابوسفیان نے نہایت بلند آہنگی سے تین مرتبہ یہی سوال دہرایا مگر جواب دینے کی اجازت نہ ملی۔ اس کے بعد ابوسفیان نے پکار لگائی:\nأَفِي الْقَوْمِ ابْنُ أَبِي قُحَافَةَ؟\n’’کیا تم لوگوں میں ابن ابی قحافہ، یعنی ابوبکر صدیق رضی اللہ عنہ زندہ ہیں؟‘‘\nرسول اللہ صلی اللہ علیہ وسلم نے اب بھی جواب دینے کی اجازت نہ دی۔ یہ سوال بھی ابوسفیان نے تین بار دہرایا۔ پھر خاموش ہو گیا۔ اس کے بعد اس نے پھر ہانک لگائی:\nأَفِي الْقَوْمِ ابْنُ الْخَطَّابِ؟\n’’کیا تم لوگوں میں ابن خطاب زندہ ہیں؟‘‘","",{"v":600284,"fn":"(1) السيرة لابن هشام: 99/3"}],[2860,"ابوسفیان نے یہ سوال بھی تین مرتبہ دہرایا مگر آپ صلی اللہ علیہ وسلم نے جواب دینے کی اجازت نہیں دی۔ اب ابوسفیان چہکنے لگا۔ اپنے رفقاء سے خوش ہو کر بولا:\nأَمَّا هَؤُلَاءِ فَقَدْ قُتِلُوا.\n’’لو، یہ سب تو قتل ہو گئے ہیں۔‘‘\nسیدنا عمر رضی اللہ عنہ اس جملے کی تاب نہ لا سکے۔ وہ ایک دم تڑپ کر چیخ اُٹھے:\nكَذَبْتَ وَاللهِ! يَا عَدُوَّ اللهِ إِنَّ الَّذِينَ عَدَدْتَ لَأَحْيَاءٌ كُلُّهُمْ، وَقَدْ بَقِيَ لَكَ مَا يَسُوءُكَ.\n’’اے اللہ کے دشمن! اللہ کی قسم! تو نے جو کچھ کہا ہے بالکل غلط کہا ہے۔ بلاشبہ جن لوگوں کے تو نے نام لیے ہیں، اللہ کے فضل سے وہ سب ابھی زندہ سلامت ہیں۔ اللہ تعالیٰ نے تیرے رنج و غم کا سامان برقرار رکھا ہوا ہے۔‘‘\nاس کے بعد ابوسفیان نے اپنے قومی بت کا نعرہ لگایا اور کہا:\nأَعْلُ هُبَلْ! أَعْلُ هُبَلْ!\n’’اے ہبل! تو بلند ہو۔ اے ہبل! تیرا بول بالا ہو۔‘‘\nاب رسول اللہ صلی اللہ علیہ وسلم نے سیدنا عمر فاروق رضی اللہ عنہ سے فرمایا:\n«أَلَا تُجِيبُوهُ؟»\n’’تم اس کو جواب کیوں نہیں دیتے؟‘‘\nصحابہ پوچھنے لگے: اے اللہ کے رسول! ہم کیا جواب دیں؟ رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمایا:\n«قُولُوا: اللهُ أَعْلَى وَأَجَلُّ»\n’’تم کہو: اللہ تعالیٰ ہی سب سے اعلیٰ اور ارفع اور بزرگ و برتر ہے۔‘‘\nابوسفیان پھر بنکارنے لگا:\nإِنَّ لَنَا الْعُزَّى، وَلَا عُزَّى لَكُمْ.\n’’ہمارے پاس عزّیٰ ہے، تمھارے پاس عزّیٰ نہیں ہے۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم نے سیدنا عمر فاروق رضی اللہ عنہ سے فرمایا:","",{"v":600285}],[2861,"«أَلَا تُجِيبُوهُ؟»\n’’تم اس کو جواب کیوں نہیں دیتے؟‘‘\nصحابہ پوچھنے لگے: اے اللہ کے رسول! ہم کیا جواب دیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n«قُولُوا: اللَّهُ مَوْلَانَا، وَلَا مَوْلَى لَكُمْ»\n’’تم کہو: اللہ ہمارا آقا و مولا ہے۔ اللہ ہمارا معین و مددگار ہے، تمھارا کوئی مولا نہیں۔‘‘\nابوسفیان بولا:\nيَوْمٌ بِيَوْمِ بَدْرٍ وَالْحَرْبُ سِجَالٌ وَتَجِدُونَ مُثْلَةً لَّمْ آمُرْ بِهَا وَلَمْ تَسُؤْنِي.\n’’یہ دن بدر کے دن کا جواب ہے، اب ہم تم برابر ہو گئے۔ لڑائی تو ڈول کی طرح ہوتی ہے۔ یہ ایک مرکز پر نہیں رہتی، کبھی ادھر کبھی ادھر، کبھی اوپر کبھی نیچے۔ تمھارے کچھ آدمیوں کا مثلہ کیا گیا ہے۔ میں نے مثلے کا حکم نہیں دیا تھا مگر یہ مجھے برا بھی نہیں لگا۔‘‘(1)\nصحیح بخاری میں ابوسفیان کے اس قول کا جواب نہیں دیا گیا لیکن سیرت ابن کثیر میں ابن عباس رضی اللہ عنہما سے مروی ہے کہ سیدنا عمر رضی اللہ عنہ نے یہ جواب دیا:\nلَا سَوَاءَ، قَتْلَانَا فِي الْجَنَّةِ، وَقَتْلَاكُمْ فِي النَّارِ.\n’’ہم اور تم ہرگز برابر نہیں۔ ہمارے مقتولین جنت میں ہیں اور تمھارے مقتولین جہنم میں۔‘‘\nاس کے بعد ابوسفیان کہنے لگا: اے عمر! ذرا میرے قریب آؤ۔ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا عمر کو حکم دیا: جاؤ، دیکھو تو کہی یہ کیا کہتا ہے۔ سیدنا عمر رضی اللہ عنہ اس کے پاس گئے۔ ابوسفیان نے کہا:\nأَنْشُدُكَ اللَّهَ يَا عُمَرُ أَقَتَلْنَا مُحَمَّدًا (صلی اللہ علیہ وسلم)؟\n’’اے عمر! تم کو اللہ کی قسم! سچ بتاؤ کیا ہم نے محمد (صلی اللہ علیہ وسلم) کو قتل کر دیا ہے؟‘‘\nسیدنا عمر رضی اللہ عنہ نے فرمایا:\nاللَّهُمَّ! لَا، وَإِنَّهُ لَيَسْمَعُ كَلَامَكَ الْآنَ.\n’’اللہ کی قسم! ہرگز نہیں۔ بلاشبہ وہ تو اس وقت بھی تیری باتیں سن رہے ہیں۔‘‘","",{"v":600286,"fn":"(1) صحيح البخاري: 3039 و 4043"}],[2862,"ابوسفیان بولا:\nأَنْتَ عِنْدِي أَصْدَقُ مِنِ ابْنِ قَمِئَةَ وَأَبَرُّ.\n’’تم میرے نزدیک ابن قمیئہ سے زیادہ سچے اور نیک ہو۔‘‘\nبعد ازاں ابوسفیان نے کہا:\nإِنَّهُ قَدْ كَانَ فِي قَتْلَاكُمْ مُثَلٌ وَاللهِ! مَا رَضِيتُ، وَمَا سَخِطْتُ، وَمَا نَهَيْتُ، وَمَا أَمَرْتُ.\n’’ہمارے آدمیوں کے ہاتھوں سے تمھارے مقتولین کا مثلہ ہوا ہے۔ اللہ کی قسم! مجھے یہ فعل اچھا لگا ہے نہ برا۔ میں نے منع کیا ہے نہ میں نے حکم دیا۔‘‘\nچلتے چلتے ابوسفیان نے کہا:\nإِنَّ مَوْعِدَكُمْ بَدْرٌ لِلْعَامِ الْقَابِلِ.\n’’اگلے سال بدر میں تم سے لڑائی کا وعدہ رہا۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم نے حکم دیا کہ اس سے کہہ دو:\n«نَعَمْ! هُوَ بَيْنَنَا وَبَيْنَكُمْ مَوْعِدٌ إِنْ شَاءَ اللهُ»\n’’ہاں! یہ ہمارا تمھارا وعدہ ہے۔ ان شاء اللہ‘‘(1)\nاس واقعے سے یہ ثابت ہوتا ہے کہ نبی صلی اللہ علیہ وسلم کے بعد ابوبکر رضی اللہ عنہ اور ان کے بعد سیدنا عمر فاروق رضی اللہ عنہ کا درجہ معروف و مسلّم تھا۔ یہ ترتیب اس قدر عام فہم، واضح اور روشن تھی کہ کفار بھی یہی سمجھتے تھے کہ آپ صلی اللہ علیہ وسلم کے بعد ابوبکر صدیق رضی اللہ عنہ اور پھر عمر فاروق رضی اللہ عنہ کا درجہ ہے۔ غرضیکہ رسول اللہ صلی اللہ علیہ وسلم کی ذات بابرکات کے بعد شیخین کی ترتیب کا مسئلہ بھی کفار کو خوب معلوم تھا۔\n§مدینہ منورہ کی حفاظت کے لیے رسول اللہ صلی اللہ علیہ وسلم کی پیش بندی\nابوسفیان نے واپس جا کر اپنے لشکر کو کوچ کا حکم دیا۔ رسول اللہ صلی اللہ علیہ وسلم کو خدشہ لاحق ہوا، مبادا ابوسفیان یہ سمجھے کہ مدینہ خالی ہے، اس لیے چلتے چلتے مدینہ پر چڑھائی کر دی جائے۔ اس طرح بچوں اور خواتین کی زندگیوں کو شدید خطرات لاحق ہو سکتے تھے، چنانچہ آپ صلی اللہ علیہ وسلم نے پیش بندی کے طور پر سیدنا علی رضی اللہ عنہ کو حکم دیا کہ کفار کی نگرانی کرو۔","",{"v":600287,"fn":"(1) السيرة النبوية لابن كثير، ص: 312، السيرة لابن هشام: 43/4"}],[2863,"اگر وہ اونٹوں پر سوار ہو جائیں اور گھوڑوں کو کوتل لے چلیں تو اس کا مطلب یہ ہوگا کہ وہ واقعی واپس مکہ جا رہے ہیں اور ان کا کوئی جارحانہ ارادہ نہیں ہے۔ اس کے برعکس اگر وہ گھوڑوں پر سوار ہوں اور اونٹوں کو خالی لے چلیں تو اس کے معنی یہ ہوں گے کہ اللہ نہ کرے وہ مدینہ پر چڑھائی کے لیے روانہ ہو رہے ہیں۔ بعد ازاں آپ صلی اللہ علیہ وسلم نے فرمایا:\n«وَالَّذِي نَفْسِي بِيَدِهِ لَئِنْ أَرَادُوهَا لَأَسِيرَنَّ إِلَيْهِمْ فِيهَا، ثُمَّ لَأُنَاجِزَنَّهُمْ»\n’’اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اگر انھوں نے مدینہ طیبہ پر چڑھائی کی تو میں فوراً ان کا تعاقب کروں گا اور ان سے جنگ کروں گا۔‘‘\nنبی صلی اللہ علیہ وسلم کے اس فرمان کے مطابق سیدنا علی المرتضیٰ رضی اللہ عنہ نے کفار قریش کے لشکر کا تعاقب کیا اور ان کی نقل و حرکت کا جائزہ لے کر واپس آ گئے۔ انھوں نے اطلاع دی کہ وہ اونٹوں پر سوار ہوتے ہیں اور گھوڑوں کو کوتل لیے جا رہے ہیں۔ ان میں چند سر پھروں نے مشورہ دیا کہ مدینہ خالی ہے، چلو لگے ہاتھوں اسے لوٹ لیں لیکن صفوان بن امیہ نے انھیں ایسا کرنے سے منع کیا اور کہا کہ فتح کو کیوں شکست میں تبدیل کرنا چاہتے ہو؟ جو ہو چکا، سو ہو چکا۔ بس اسی کو غنیمت سمجھو اور سیدھے مکہ چلے چلو۔(1)","",{"v":600288,"fn":"(1) المغازي للواقدي: 255,256/1، السيرة لابن إسحاق: 343/1، السيرة لابن هشام: 100/3، الروض الأنف: 280/3۔ واقدی نے سیدنا علی رضی اللہ عنہ کی جگہ سیدنا سعد بن ابی وقاص رضی اللہ عنہ کو بھیجنے کا ذکر کیا ہے۔"}],[2864,"لڑائی کے بعد کے حالات\n§رسول اللہ صلی اللہ علیہ وسلم کے زخموں کی دیکھ بھال\nرسول اللہ صلی اللہ علیہ وسلم کا چہرہ انور جنگ احد میں زخمی ہو گیا تھا۔ سامنے سے نچلا دایاں رباعی دانت ٹوٹ گیا تھا۔ خود کے دو حلقے رخسار مبارک میں پیوست ہو گئے تھے، نچلا ہونٹ پھٹ گیا تھا اور گھٹنے بھی زخمی تھے۔ جب رسول اللہ صلی اللہ علیہ وسلم نے گھائی میں دم لیا تو سیدنا علی رضی اللہ عنہ نے زخموں کی مرہم پٹی کی طرف توجہ کی جن سے ابھی تک خون بہہ رہا تھا۔ سیدنا علی رضی اللہ عنہ مہراس سے اپنی ڈھال میں پانی بھر لائے۔ مہراس کے بارے میں کہا جاتا ہے کہ یہ پتھر میں بنا ہوا گڑھا ہوتا ہے جس میں زیادہ پانی جمع ہو جاتا ہے۔ یہ بھی کہا جاتا ہے کہ مہراس احد میں ایک چشمے کا نام تھا۔ بہر حال سیدنا علی رضی اللہ عنہ نے وہاں سے لایا ہوا پانی نبی صلی اللہ علیہ وسلم کی خدمت میں پینے کے لیے پیش کیا۔ آپ صلی اللہ علیہ وسلم نے اس پانی میں قدرے بو محسوس کی تو اسے نوش نہیں فرمایا، البتہ اس سے اپنا چہرہ مبارک دھو لیا اور سر پر ڈال لیا۔ اس حالت میں آپ صلی اللہ علیہ وسلم فرما رہے تھے:\n«اشْتَدَّ غَضَبُ اللهِ عَلَى قَوْمٍ فَعَلُوا بِنَبِيِّهِ»\n’’اس قوم پر اللہ تعالیٰ کا سخت غضب نازل ہو جو اپنے نبی کے ساتھ یہ سلوک کرے۔‘‘\nآپ صلی اللہ علیہ وسلم کا اشارہ اپنے دانت کے ٹوٹنے کی طرف تھا۔ آپ صلی اللہ علیہ وسلم نے یہ بھی فرمایا:\n«اشْتَدَّ غَضَبُ اللهِ عَلَى رَجُلٍ يَقْتُلُهُ رَسُولُ اللهِ فِي سَبِيلِ اللهِ»\n’’اللہ تعالیٰ کا سخت غضب ہو اس شخص پر جسے اللہ کا رسول اللہ کے رستے میں قتل کر دے۔‘‘\nابن عباس رضی اللہ عنہما کی روایت میں یہ الفاظ ہیں:\n«اشْتَدَّ غَضَبُ اللهِ عَلَى قَوْمٍ دَمَّوْا وَجْهَ نَبِيِّ اللهِ»\n’’اللہ تعالیٰ کا سخت غضب ہو اس قوم پر جس نے اللہ کے نبی کے چہرے کو زخمی کر دیا ہے۔‘‘(1)","",{"v":600289,"fn":"(1) صحيح البخاري: 4073,4074، صحيح مسلم: 1793، مسند أحمد: 287,288/1، السيرة لابن هشام: 90,91/3"}],[2865,"سیدنا سہل رضی اللہ عنہ فرماتے ہیں: مجھے معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم کا زخم کس نے دھویا، پانی کس نے بہایا اور علاج کس چیز سے کیا گیا۔ آپ کی لخت جگر سیدہ فاطمہ رضی اللہ عنہا آپ کا زخم دھو رہی تھیں، سیدنا علی رضی اللہ عنہ ڈھال سے پانی ڈالتے جاتے تھے۔ جب سیدہ فاطمہ رضی اللہ عنہا نے دیکھا کہ پانی بہانے کے باوجود خون بہتا ہی جا رہا ہے تو انھوں نے چٹائی کا ایک ٹکڑا لیا، اسے جلایا اور اس کی راکھ زخموں پر چپکا دی۔ اس طرح خون رک گیا۔(1)\nسیدنا محمد بن مسلمہ رضی اللہ عنہ نے محسوس کیا کہ نبی صلی اللہ علیہ وسلم کو پیاس لگ رہی ہے، چنانچہ وہ میٹھے اور صاف پانی کی تلاش میں نکلے۔ پہلے ان مسلم خواتین کی خدمت میں پہنچے جو مشکیں بھر بھر کر زخمیوں کو پانی پلا رہی تھیں۔ ان کا خیال تھا کہ شاید ان عظیم خواتین کے پاس تھوڑا بہت پانی موجود ہو گا لیکن ان سب کے مشکیزے خالی تھے۔ وہ یہاں سے قناة کے نالے پر چلے گئے۔ وہ صاف پانی سے بھرا ہوا بہہ رہا تھا۔ انھوں نے برتن میں یہ پانی بھر لیا۔ یہ پانی بہت ٹھنڈا اور میٹھا تھا۔ انھوں نے یہی پانی رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں پیش کیا۔ نبی صلی اللہ علیہ وسلم نے وہ پانی نوش فرمایا اور محمد بن مسلمہ رضی اللہ عنہ کو دعائے خیر دی۔(2)\nزخموں کی شدید اذیت کی وجہ سے نبی صلی اللہ علیہ وسلم نے ظہر کی نماز بیٹھے بیٹھے ہی پڑھی۔ صحابہ کرام رضی اللہ عنہم نے بھی آپ صلی اللہ علیہ وسلم کے پیچھے بیٹھ کر نماز ادا کی۔(3)\n§شہداء کی خبر گیری\nجب کفار مکہ میدان سے جا چکے تو مسلمان اپنے شہداء کی خبر گیری کے لیے ان کی تلاش میں نکلے۔ کئی صحابہ کی نعشوں کی بے حرمتی اور مثلہ کیا گیا تھا سوائے حنظلہ غسیل الملائکہ رضی اللہ عنہ کی لاش کے۔ عین ممکن ہے کہ فرشتوں نے ان کے غسل کے لیے حصار بنا رکھا ہو۔\n§سعد بن ربیع رضی اللہ عنہ کی تلاش کا حکم\nرسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n«مَنْ يَنْظُرُ لِي مَا فَعَلَ سَعْدُ بْنُ الرَّبِيعِ؟ أَفِي الْأَحْيَاءِ هُوَ أَمْ فِي الْأَمْوَاتِ فَإِنِّي رَأَيْتُ اثْنَيْ عَشَرَ رُمْحًا شُرِعَتْ إِلَيْهِ»\n’’تم میں سے کوئی ہے جو سعد بن ربیع رضی اللہ عنہ کی خبر لے آئے؟ آیا وہ زندہ ہیں یا شہید ہو چکے؟ کیونکہ میں","",{"v":600290,"fn":"(1) صحيح البخاري: 4075، صحيح مسلم: 1790\n(2) المغازي للواقدي: 221/1، سبل الهدى والرشاد: 210/4\n(3) السيرة لابن هشام: 92/3"}],[2866,"نے دیکھا ہے کہ انھیں بیک وقت بارہ نیزے گھونپے جا رہے تھے۔(1)\nامام حاکم کی روایت ہے کہ آپ صلی اللہ علیہ وسلم نے زید بن ثابت رضی اللہ عنہ کو بھیجا۔ حافظ ابن عبدالبر کی روایت میں ہے کہ ابی بن کعب رضی اللہ عنہ کو بھیجا اور واقدی کی روایت میں ہے کہ محمد بن مسلمہ رضی اللہ عنہ کو بھیجا۔ برہان الدین کہتے ہیں: ہو سکتا ہے کہ یکے بعد دیگرے تینوں کو بھیجا ہو یا بیک وقت تینوں حضرات کو یہ حکم صادر فرمایا ہو۔(2)\nزید بن ثابت رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے حکم دیا:\n«إِنْ رَأَيْتَهُ فَأَقْرِئْهُ مِنِّي السَّلَامَ وَقُلْ لَهُ: يَقُولُ لَكَ رَسُولُ اللهِ: كَيْفَ تَجِدُكَ؟»\n’’سعد بن ربیع کو دیکھو تو انھیں میری طرف سے سلام کہنا اور ان سے یہ بھی کہنا کہ رسول اللہ صلی اللہ علیہ وسلم تمھارا حال دریافت کر رہے ہیں اور پوچھتے ہیں کہ تم اپنے آپ کو کیسا پاتے ہو؟‘‘\nزید بن ثابت رضی اللہ عنہ فرماتے ہیں کہ میں کھوج لگاتے لگاتے سعد بن ربیع رضی اللہ عنہ کے پاس جا پہنچا۔ ابھی ان میں زندگی کی رمق باقی تھی، جسم پر تیر اور تلوار کے ستر زخم تھے، میں نے رسول اللہ صلی اللہ علیہ وسلم کا سلام اور پیغام پہنچایا۔ سعد بن ربیع رضی اللہ عنہ نے یہ جواب دیا:\nعَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ السَّلَامُ، وَعَلَيْكَ السَّلَامُ، وَقُلْ لَهُ: يَا رَسُولَ اللهِ! إِنِّي أَجِدُ رِيحَ الْجَنَّةِ، وَقُلْ لِقَوْمِي الْأَنْصَارِ: لَا عُذْرَ لَكُمْ عِنْدَ اللهِ أَنْ يُخْلَصَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَفِيكُمْ شُفْرٌ يَطْرِفُ.\n’’رسول اللہ (صلی اللہ علیہ وسلم) پر سلام ہو اور تم پر بھی سلام ہو۔ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں میرا یہ پیغام پہنچا دینا کہ اے اللہ کے رسول! میں اس وقت جنت کی خوشبو سونگھ رہا ہوں اور میری قوم انصار سے کہنا کہ اگر رسول اللہ صلی اللہ علیہ وسلم کو کوئی ادنیٰ سی تکلیف بھی پہنچی اور تم میں سے ایک آنکھ بھی دیکھنے والی موجود ہوئی تو خوب جان لو کہ اللہ کے ہاں تمھارا کوئی عذر قبول نہیں ہو گا۔‘‘\nابھی یہی الفاظ کہے تھے کہ سعد بن ربیع رضی اللہ عنہ کی روح پرواز کر گئی۔(3)\nایک دوسری روایت میں ہے کہ سعد بن ربیع رضی اللہ عنہ نے کہا:\nأَخْبِرْ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنِّي فِي الْأَمْوَاتِ وَأَقْرِئْهُ السَّلَامَ، وَقُلْ لَهُ: يَقُولُ سَعْدٌ: جَزَاكَ اللهُ عَنَّا","",{"v":600291,"fn":"(1) السيرة النبوية لابن كثير، ص: 313، المستدرك للحاكم: 222/3، دلائل النبوة للبيهقي: 248/3، الروض الأنف: 281/3\n(2) شرح الزرقاني على المواهب: 445/2\n(3) المستدرك للحاكم: 221/3، دلائل النبوة للبيهقي: 248/3"}],[2867,"وَعَنْ جَمِيعِ الْأُمَّةِ خَيْرًا.\n’’رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں یہ اطلاع پہنچا دینا کہ میں اس وقت مر رہا ہوں اور سلام کے بعد میری طرف سے یہ عرض کر دینا کہ سعد کہتا تھا: اے اللہ کے رسول! اللہ تعالیٰ آپ کو ہماری طرف سے اور پوری امت کی طرف سے خوب سے خوب تر جزا دے (کیونکہ آپ نے ہمیں حق کا رستہ بتایا ہے)۔‘‘\nابن عبدالبر کی روایت میں سیدنا ابی بن کعب رضی اللہ عنہ سے مروی ہے کہ میں واپس آیا اور سعد کی ساری باتیں جناب رسول اللہ صلی اللہ علیہ وسلم کے گوش گزار کر دیں تو آپ صلی اللہ علیہ وسلم نے ارشاد فرمایا:\n«رَحِمَهُ اللهُ، نَصَحَ لِلَّهِ وَلِرَسُولِهِ حَيًّا وَمَيِّتًا»\n’’اللہ اس پر رحمت کی برکھا برسائے، وہ زندگی میں بھی اور مرتے وقت بھی اللہ اور اس کے رسول ہی کا خیر خواہ اور وفادار رہا۔‘‘(1)\n§سید الشہداء حمزہ بن عبدالمطلب رضی اللہ عنہ کی تلاش\nرسول اللہ صلی اللہ علیہ وسلم بار بار سیدنا حمزہ رضی اللہ عنہ کے بارے میں یہی دریافت فرماتے تھے:\n«مَا فَعَلَ عَمِّي؟ مَا فَعَلَ عَمِّي؟»\n’’میرے چچا جان نے کیا کیا ہے؟ مجھے میرے چچا جان کا کارنامہ بتاؤ۔‘‘\nایک شخص نے عرض کی: میں نے انھیں ابھی چٹانوں کے پاس دیکھا ہے، وہ کہہ رہے تھے:\nأَنَا أَسَدُ اللهِ وَأَسَدُ رَسُولِهِ، اللَّهُمَّ أَبْرَأُ إِلَيْكَ مِمَّا جَاءَ بِهِ هَؤُلَاءِ أَبُو سُفْيَانَ وَأَصْحَابُهُ وَأَعْتَذِرُ إِلَيْكَ مِمَّا صَنَعَ هَؤُلَاءِ بِانْهِزَامِهِمْ.\n’’میں اللہ کا شیر ہوں۔ میں اس کے رسول کا شیر ہوں۔ اے اللہ! میں ان کفار، یعنی ابوسفیان اور اس کے ساتھیوں کی کارستانیوں سے براءت کا اظہار کرتا ہوں اور ان مسلمانوں نے جو راہ فرار اختیار کی ہے، اس کے لیے معافی کی درخواست کرتا ہوں۔‘‘\nچنانچہ سیدنا حارث بن صمہ رضی اللہ عنہ سیدنا حمزہ رضی اللہ عنہ کی تلاش میں نکلے۔ وہ انھیں دیر تک ڈھونڈتے رہے، پھر سیدنا علی رضی اللہ عنہ تلاش کے لیے نکلے۔ انھوں نے تلاش بسیار کے بعد ان کا لاشہ وادی کے وسط میں خون میں نہایا ہوا پایا۔ وہ","",{"v":600292,"fn":"(1) المستدرك للحاكم: 222/3، الاستيعاب، ص: 310"}],[2868,"نہایت بوجھل دل سے واپس آئے۔ نبی صلی اللہ علیہ وسلم کی خدمت میں صورت حال عرض کر دی کہ سیدنا حمزہ رضی اللہ عنہ کا پیٹ چاک کر دیا گیا ہے۔ جسم کے ٹکڑے کر دیے گئے ہیں۔ بعد ازاں رسول اللہ صلی اللہ علیہ وسلم نے اپنے چچا کی میت پر نگاہ ڈالی۔ آپ صلی اللہ علیہ وسلم نے اس قدر بھیانک منظر کبھی نہ دیکھا تھا۔ شفیق چچا کی چھلنی لاش دیکھ کر آپ صلی اللہ علیہ وسلم اس قدر روئے کہ ہچکی بندھ گئی۔ اللہ کی توحید کے اعلان اور محبت رسالت کے جرم میں حمزہ رضی اللہ عنہ کی لاش کا مثلہ کر دیا گیا تھا۔ آہ! یہ کتنا روح فرسا اور کیسا الم انگیز منظر تھا جسے دیکھ کر صبر و استقامت کے کوہ گراں سیدنا محمد صلی اللہ علیہ وسلم کی مبارک آنکھیں بھی بھیگ گئیں۔ رسول اللہ صلی اللہ علیہ وسلم نے عم محترم کی لاش پر آخری نگاہ ڈالی اور رنج و قلق میں ڈوبے ہوئے لہجے میں ارشاد فرمایا:\n«رَحْمَةُ اللهِ عَلَيْكَ، فَإِنَّكَ كُنْتَ مَا عَلِمْتُكَ إِلَّا فَعَّالًا لِلْخَيْرَاتِ وَصُولًا لِلرَّحِمِ»\n’’(اے میرے شفیق چچا جان!) آپ پر اللہ کی رحمتیں ہوں۔ میں تو یہی جانتا ہوں کہ آپ بہت بھلائیاں کرنے والے اور خوب صلہ رحمی کرنے والے تھے۔‘‘(1)\nمزید فرمایا:\n«لَوْلَا أَنْ تَحْزَنَ النِّسَاءُ أَوْ تَكُونَ سُنَّةً بَعْدِي لَتَرَكْتُهُ حَتَّى يَبْعَثَهُ اللهُ مِنْ بُطُونِ السِّبَاعِ وَالطَّيْرِ، لَأَمْثُلَنَّ مَكَانَهُ بِسَبْعِينَ رَجُلًا»\n’’اگر مجھے یہ اندیشہ نہ ہوتا کہ عورتیں بہت غمزدہ ہوں گی یا میرے بعد یہ سنت جاری ہو جائے گی تو میں حمزہ کو اسی حالت میں چھوڑ دیتا تا کہ قیامت کے دن ان کا ظہور درندوں کے شکموں اور پرندوں کے پیٹوں سے ہوتا۔ (اگر اللہ تبارک و تعالیٰ نے مجھے مشرکین پر غلبہ دیا تو) میں چچا کے بدلے میں ان کے ستر آدمیوں کا مثلہ کروں گا۔‘‘\nپھر فرمایا:\n«أَبْشِرُوا، جَاءَنِي جِبْرِيلُ فَأَخْبَرَنِي أَنَّ حَمْزَةَ مَكْتُوبٌ فِي أَهْلِ السَّمَاوَاتِ السَّبْعِ: حَمْزَةُ بْنُ عَبْدِ الْمُطَّلِبِ أَسَدُ اللهِ وَأَسَدُ رَسُولِهِ»\n’’خوش ہو جاؤ، میرے پاس جبریل آئے تھے، انھوں نے مجھے خبر دی کہ بلاشبہ حمزہ رضی اللہ عنہ کا ساتوں آسمانوں میں نام نامی یہ لکھا گیا ہے: اللہ اور اس کے رسول کا شیر حمزہ بن عبدالمطلب۔‘‘\nاس پُر ملال موقع پر اللہ تبارک و تعالیٰ نے آپ صلی اللہ علیہ وسلم کے مجروح دل کی تسکین کے لیے یہ آیت نازل فرمائی:","",{"v":600293,"fn":"(1) شعب الإيمان للبيهقي: 120/7"}],[2869,"﴿وَإِنْ عَاقَبْتُمْ فَعَاقِبُوا بِمِثْلِ مَا عُوقِبْتُمْ بِهِ وَلَئِنْ صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّابِرِينَ ۝ وَاصْبِرْ وَمَا صَبْرُكَ إِلَّا بِاللهِ وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُ فِي ضَيْقٍ مِمَّا يَمْكُرُونَ ۝﴾\n’’اور اگر تم بدلہ لو تو اتنا ہی بدلہ لو جتنی تمھیں تکلیف دی گئی ہے اور اگر تم صبر کرو تو وہ صبر کرنے والوں کے لیے بہت بہتر ہے۔ اور (اے نبی!) آپ صبر کریں اور آپ کا صبر کرنا بھی اللہ ہی کی توفیق سے ہے اور ان (کفار) پر غم نہ کھائیں، نہ آپ اس پر تنگی میں مبتلا ہوں جو وہ مکر (سازشیں) کرتے ہیں۔‘‘(1)\nاس آیت کے نازل ہونے کے بعد رسول اللہ صلی اللہ علیہ وسلم نے صبر اختیار فرمایا، مشرکین کی کسی لاش کا مثلہ نہیں کیا اور اپنے امتیوں کو بھی مثلے کی ممانعت فرما دی اور قسم کا کفارہ دے دیا۔(2)\nبعض روایات میں ہے کہ درج بالا آیات مبارکہ فتح مکہ کے موقع پر نازل ہوئی تھیں۔(3) ایک قول یہ بھی ہے کہ یہ آیات مکی ہیں۔(4) ہو سکتا ہے کہ تینوں موقعوں ہی پر یہ آیات نازل ہوئی ہوں کیونکہ کسی آیت کا متعدد بار نزول ممکن ہے۔(5)\nسیدنا جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جب سیدنا حمزہ رضی اللہ عنہ کا حال زار دیکھا تو رو پڑے۔ اس قدر روئے کہ ہچکی بندھ گئی۔ بعد ازاں فرمایا:\n«سَيِّدُ الشُّهَدَاءِ عِنْدَ اللهِ تَعَالَى يَوْمَ الْقِيَامَةِ حَمْزَةُ»\n’’قیامت کے دن اللہ کے نزدیک تمام شہیدوں کے سردار حمزہ ہوں گے۔‘‘(6)\nسیدنا حمزہ بن عبدالمطلب رضی اللہ عنہ تمام شہیدوں کے سردار ہیں۔ اسی وجہ سے سیدنا حمزہ رضی اللہ عنہ سید الشہداء کے لقب سے مشہور ہوئے۔(7)\n§رسول اللہ صلی اللہ علیہ وسلم کی حمزہ نام سے محبت\nرسول اللہ صلی اللہ علیہ وسلم کو اپنے چچا حمزہ رضی اللہ عنہ سے شدید محبت تھی۔ آپ صلی اللہ علیہ وسلم کو محض شفیق چچا کی شخصیت ہی سے پیار نہ تھا بلکہ ان کا اسم گرامی بھی بہت محبوب تھا۔ سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں: ہم میں سے ایک شخص کو اللہ تعالیٰ نے بیٹا عطا فرمایا تو اس کے گھر والوں نے رسالت مآب صلی اللہ علیہ وسلم سے پوچھا: اس کا نام کیا رکھیں؟ نبی کریم صلی اللہ علیہ وسلم نے فرمایا:","",{"v":600294,"fn":"(1) النحل 16:126,127\n(2) سنن الدارقطني: 117/4، المعجم الكبير للطبراني: 62/11، المستدرك للحاكم: 197/3 و 199، سبل الهدى والرشاد: 223/4\n(3) جامع الترمذي: 3129\n(4) دلائل النبوة للبيهقي: 289/3\n(5) البداية والنهاية (محقق): 214/4\n(6) دیکھئے: شرح الزرقاني على المواهب: 448,449/2، المستدرك للحاكم: 219/3، صحيح الجامع للألباني: 3676\n(7) فتح الباري: 459/7"}],[2870,"«سَمُّوهُ بِأَحَبِّ الْأَسْمَاءِ إِلَيَّ: حَمْزَةَ بْنَ عَبْدِ الْمُطَّلِبِ»\n’’اس کا نام حمزہ بن عبدالمطلب کے نام پر رکھو کیونکہ ان کا نام مجھے سب ناموں سے زیادہ پیارا ہے۔‘‘(1)\n§سیدہ صفیہ رضی اللہ عنہا کی استقامت\nسیدہ صفیہ رضی اللہ عنہا سیدنا حمزہ رضی اللہ عنہ کی سگی بہن تھیں۔ انھیں خبر ملی کہ سیدنا حمزہ رضی اللہ عنہ شہید ہو گئے ہیں تو وہ میدان احد میں اپنے پیارے بھائی کی نعش دیکھنے کے لیے آئیں۔ رسول اللہ صلی اللہ علیہ وسلم نے انھیں دور سے آتے دیکھ لیا۔ آپ صلی اللہ علیہ وسلم کو اندیشہ ہوا مبادا وہ اپنے بھائی کی نعش کو اس پراگندہ حالت میں دیکھ کر صبر کا دامن چھوڑ دیں اور انتہائی دکھی اور پریشان ہو جائیں، چنانچہ آپ صلی اللہ علیہ وسلم نے ان کے بیٹے سیدنا زبیر رضی اللہ عنہ کو حکم دیا:\n«الْقَهَا فَأَرْجِعُهَا، لَا تَرَى مَا بِأَخِيهَا»\n’’آپ اپنی والدہ ماجدہ کے پاس جائیں اور انھیں وہیں سے واپس بھیج دیں تا کہ وہ اپنے بھائی کو نہ دیکھ سکیں کہ اُن کی کیا حالت ہو گئی ہے۔‘‘\nسیدنا زبیر رضی اللہ عنہ اپنی والدہ کو روکنے کے لیے دوڑ پڑے۔ وہ والدہ ماجدہ تک پہنچے اور انھیں میدان میں جانے سے روکنے لگے۔ سیدہ صفیہ رضی اللہ عنہا نے سیدنا زبیر رضی اللہ عنہ کے سینے پر زور سے گھونسا مارا اور فرمایا: ہٹ جاؤ میرے سامنے\n[تصویر: صفیہ بنت عبدالمطلب کے نام سے منسوب اسکول کی عمارت، جس کے بورڈ پر انگریزی میں SAFIA BINT ABD AL MUTALEB for Basic Education لکھا ہے]","",{"v":600295,"fn":"(1) المستدرك للحاكم: 216/3، حديث: 4888، سلسلة الأحاديث الصحيحة: 887/6","im":["v6_p295.jpg"]}],[2871,"سے۔ سیدنا زبیر رضی اللہ عنہ نے عرض کیا: امی جان! رسول اللہ صلی اللہ علیہ وسلم نے آپ کو میدان جنگ میں آنے کی ممانعت فرمائی ہے، لہذا آپ واپس تشریف لے جائیں۔ سیدہ صفیہ رضی اللہ عنہا بولیں:\nوَلِمَ؟ وَقَدْ بَلَغَنِي أَنْ قَدْ مُثِّلَ بِأَخِي، وَذَلِكَ فِي اللهِ فَمَا أَرْضَانَا بِمَا كَانَ مِنْ ذَلِكَ لَأَحْتَسِبَنَّ وَلَأَصْبِرَنَّ إِنْ شَاءَ اللهُ.\n’’کیوں؟ مجھے معلوم ہو گیا ہے کہ میرے بھائی کا مثلہ کر دیا گیا ہے لیکن یہ سب کچھ اللہ کی راہ میں ہوا ہے۔ پس اس نے جس طرح ہمیں راضی کیا ہے، ان شاء اللہ میں اس مصیبت پر صبر کروں گی اور ثواب کی امید رکھوں گی۔‘‘\nسیدنا زبیر رضی اللہ عنہ نے اپنی والدہ محترمہ کے اس جواب سے رسول اللہ صلی اللہ علیہ وسلم کو مطلع کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n«خَلِّ سَبِيلَهَا»\n’’ٹھیک ہے، ان کا راستہ چھوڑ دو۔‘‘\nجب سیدہ صفیہ رضی اللہ عنہا اپنے بھائی سیدنا حمزہ بن عبدالمطلب رضی اللہ عنہ کی مثلہ شدہ نعش کے پاس پہنچیں تو بڑے صبر کے ساتھ إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ پڑھا اور ان کے لیے مغفرت کی دعائیں کی۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کا صبر دیکھا تو آپ صلی اللہ علیہ وسلم کو اندیشہ ہوا مبادا ان کی عقل پر اثر پڑ جائے، چنانچہ آپ صلی اللہ علیہ وسلم نے ان کے سینے پر ہاتھ رکھا تو سیدہ صفیہ رضی اللہ عنہا رو پڑیں۔ اس طرح ان کے غم کا بوجھ ہلکا ہو گیا۔(1)\n§حمزہ رضی اللہ عنہ کی تکفین\nابن عباس رضی اللہ عنہما سے روایت ہے کہ صفیہ رضی اللہ عنہا دو سفید چادریں ساتھ لائی تھیں۔ کہنے لگیں کہ یہ دونوں چادریں میں بھائی کے لیے لائی ہوں۔ مجھے ان کے شہید ہونے کی اطلاع مل گئی تھی۔ انھیں ان چادروں کا کفن دے کر دفنا دیجیے۔ ہم وہ دونوں چادریں لے گئے تا کہ حمزہ رضی اللہ عنہ کو کفنا دیا جائے۔ ہماری نظر سیدنا حمزہ رضی اللہ عنہ کے پہلو میں گئی تو دیکھا کہ ایک انصاری کے ساتھ بھی مشرکین نے ویسا ہی سلوک کیا تھا جیسا سیدنا حمزہ رضی اللہ عنہ سے کیا گیا تھا۔ ہمیں بڑی شرم آئی کہ ہم انصاری کی لاش تو بے کفن رہنے دیں اور سیدنا حمزہ رضی اللہ عنہ کو دو چادروں سے کفنا دیں، چنانچہ ہم نے ایک چادر حمزہ رضی اللہ عنہ کے لیے اور ایک چادر انصاری رضی اللہ عنہ کے لیے مخصوص کر دی۔","",{"v":600296,"fn":"(1) السيرة لابن هشام: 103/3، الروض الأنف: 283/3، سبل الهدى والرشاد: 224/4"}],[2872,"سیدنا انس رضی اللہ عنہ روایت فرماتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے سیدنا حمزہ رضی اللہ عنہ کو ایک سیاہ دھاریوں والی چادر کا کفن دیا۔ ہم اس سے سر ڈھانپتے تو پاؤں ننگے ہو جاتے تھے اور پاؤں ڈھانپتے تو سر ننگا ہو جاتا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے حکم فرمایا:\n﴿أَنْ يَمُدُّوهَا عَلَى رَأْسِهِ وَيَجْعَلُوا عَلَى رِجْلَيْهِ مِنَ الْإِذْخِرِ﴾\n’’چادر کے ذریعے سے ان کا سر ڈھانپ دو اور ان کے دونوں پاؤں پر اذخر گھاس ڈال دو۔‘‘(1)\n§عبداللہ بن جحش رضی اللہ عنہ کی شہادت\nسیدنا عبداللہ بن جحش اور سیدنا سعد بن ابی وقاص رضی اللہ عنہما کی دعا کا تذکرہ شروع میں ہو چکا ہے۔ دونوں کی دعا قبول ہوئی۔ سیدنا عبداللہ بن جحش رضی اللہ عنہ نے دعا کی تھی کہ اے رب العالمین! میرے مقابلے میں ایک ایسا کافر بھیج جو بڑا تنومند اور قوی ہو اور سپہ گری میں ید طولیٰ رکھتا ہو۔ جب ہمارا مقابلہ ہو تو میں تیری رضا کے لیے جنگ کروں، وہ مجھے قتل کر دے۔ میرے ناک اور کان کاٹ دے۔ قیامت کے دن جب آپ سے ملاقات ہو تو آپ مجھ سے دریافت فرمائیں: اے میرے بندے! تیرے ناک اور کان کس جرم میں کاٹے گئے؟ تو میں عرض کروں: اے اللہ! آپ کے رستے میں، آپ کی رضا کے لیے میرا یہ حال ہوا ہے۔ اس وقت آپ مجھ سے فرمائیں کہ اے میرے بندے! تو نے سچ کہا۔\nسعد رضی اللہ عنہ فرماتے ہیں کہ ان کی دعا میری دعا سے کہیں بہتر تھی۔ میں نے شام کو دیکھا کہ ان کے ناک اور کان کٹے ہوئے تھے۔(2)\nسعید بن مسیب رحمہ اللہ فرماتے ہیں کہ میں اللہ تعالیٰ سے امید رکھتا ہوں کہ جس طرح حق تعالیٰ نے ان کی شہادت کے بارے میں دعا قبول فرمائی ہے، اسی طرح اللہ تعالیٰ نے ان کی دوسری دعا بھی ضرور قبول کی ہوگی، یعنی شہید ہونے کے بعد ان سے یہ سوال ضرور ہوگا: یہ حال کیوں ہوا؟ اور عبداللہ بن جحش رضی اللہ عنہ ضرور جواب دیں گے: ’’اے اللہ! تیری رضا کے لیے، تیرے رستے میں۔‘‘(3)\nسیدنا عبداللہ بن جحش رضی اللہ عنہ جب مصروف پیکار تھے تو ان کی تلوار ٹوٹ گئی۔ مجاہدین کے پاس اسلحہ وافر نہیں تھا، چنانچہ سیدنا عبداللہ بن جحش رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے اور عرض کی کہ میری تلوار ٹوٹ گئی ہے۔","",{"v":600297,"fn":"(1) المستدرك للحاكم: 120/2، مسند أحمد: 165/1، إرواء الغليل: 166/3\n(2) زاد المعاد: 208/3، الروض الأنف: 284,285/3\n(3) المستدرك للحاكم: 200/3"}],[2873,"رسول اللہ صلی اللہ علیہ وسلم کے پاس کوئی دوسری تلوار نہ تھی۔ آپ نے کھجور کی ایک شاخ پکڑا دی۔ سیدنا عبداللہ بن جحش رضی اللہ عنہ نے وہ شاخ پکڑی اور اسے لہرایا تو وہ شمشیر جوہردار بن گئی۔ اسی تلوار سے آپ لڑتے رہے یہاں تک کہ شہید ہو گئے۔ اس تلوار کا نام العرجون تھا۔ یہ تلوار آپ کی اولاد میں وراثتاً چلتی رہی یہاں تک کہ معتصم بن ہارون الرشید کے سالار بغا الترکی نے دو سو دینار کے عوض بیچ ڈالی۔(1)\nاسی وجہ سے سیدنا عبداللہ بن جحش رضی اللہ عنہ مُجَدَّع فی اللہ کہلائے، یعنی وہ شخص جس کے ناک اور کان اللہ کی راہ میں کاٹے گئے۔(2)\nمولانا محمد ادریس کاندھلوی رحمہ اللہ سیدنا عبداللہ بن جحش رضی اللہ عنہ کی دعا اور اس کی قبولیت پر رقم طراز ہیں:\n’’اللہ تبارک و تعالیٰ کے محبین و مخلصین اور والہین کا یہی حال ہوتا ہے کہ وہ اللہ کی راہ میں جان دینا اپنی انتہائی سعادت اور خوش بختی سمجھتے ہیں، بمقابلہ حیات، موت ان کو زیادہ لذیذ اور خوشگوار معلوم ہوتی ہے، اس لیے کہ وہ موت کو محبوب حقیقی (یعنی حق تعالیٰ شانہ) کی ملاقات کا ذریعہ اور سجن دنیا سے رہا ہو کر گلستان جنت میں پہنچ جانے کا وسیلہ سمجھتے ہیں۔‘‘\nاللہ تعالیٰ نے جب انسان کو خلیفہ بنانے کا ارادہ فرمایا تو فرشتوں نے عرض کیا:\n﴿أَتَجْعَلُ فِيهَا مَنْ يُفْسِدُ فِيهَا وَيَسْفِكُ الدِّمَاءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ﴾\n’’کیا آپ اس شخص کو زمین میں خلیفہ بنانا چاہتے ہیں کہ جو زمین میں فساد اور خونریزی کرے، حالانکہ ہم (سب ہر لمحہ اور ہر لحظہ) تیری ستائش کے ساتھ تسبیح و تقدیس کرتے رہتے ہیں۔‘‘(3)\nانسان میں دو قوتیں ہوتی ہیں۔ ایک قوت شہویہ جس سے زنا وغیرہ صادر ہوتا ہے جس کو ملائکہ نے ﴿مَنْ يُفْسِدُ فِيهَا﴾ سے تعبیر کیا اور دوسری قوت غضبیہ جس سے قتل، حرب و ضرب اور خونریزی ظہور میں آتی ہے جس کو ملائکہ نے ﴿وَيَسْفِكُ الدِّمَاءَ﴾ سے تعبیر کیا۔\nملائکہ نے انسان کے یہ نقائص ذکر کیے۔ لیکن یہ خیال نہ کیا کہ یہی قوت شہویہ جب اس کا رخ اللہ کی طرف پھیر دیا جائے گا تو اس سے وہ ثمرات و نتائج ظاہر ہوں گے کہ فرشتے بھی عش عش کرنے لگیں گے۔ یعنی محبت خداوندی اور اس کا جوش اور ولولہ، اور علیٰ ہذا جب قوت غضبیہ کو کارخانہ خداوندی میں صرف کیا جاتا ہے تو اس سے بھی عجیب و غریب","",{"v":600298,"fn":"(1) الاكتفاء بما تضمنه من مغازي رسول الله صلى الله عليه وسلم: 83/2، تاريخ الإسلام (السيرة) للذهبي، ص: 185، سيدنا محمد رسول الله للصاغرجي، ص: 362\n(2) الإصابة: 32/4\n(3) البقرة 2:30"}],[2874,"نتائج و ثمرات ظہور میں آتے رہتے ہیں جسے فرشتے دیکھ کر حیران رہ جاتے ہیں۔ یعنی اللہ تعالیٰ کی راہ میں جانبازی اور سرفروشی اور اس کے دشمن سے جہاد و قتال۔\nفرشتے بے شک لیل و نہار اللہ تعالیٰ کی تسبیح و تقدیس کرتے ہیں مگر اس کی راہ میں جانبازی اور سرفروشی کا ولولہ ان میں نہیں۔ وہ اس دولت و نعمت سے محروم ہیں اور پھر یہ کہ اس محبوب حقیقی کے لیے جان دے دینا اور اس کی راہ میں شہید ہونا یہ وہ نعمت ہے کہ جس کا فرشتوں میں کوئی امکان نہیں، انسان میں اگرچہ فرشتوں کی طرح عصمت نہیں، لیکن گناہ کے بعد انسان کی مضطربانہ ندامت و شرمساری اور بے تابانہ گریہ و زاری اس کو اس درجہ رفیع بنا دیتی ہے کہ فرشتے نیچے رہ جاتے ہیں۔\nاسی وجہ سے اہل سنت و الجماعت کا اجماع ہے کہ تمام انبیاء و مرسلین ملائکہ مقربین سے افضل اور برتر ہیں اور صحابہ، تابعین، صدیقین، شہداء اور صالحین بقیہ ملائکہ سماوات و ارضین سے اشرف ہیں۔ اور مومنات صالحات حور عین سے افضل ہیں۔ کذا فی الیواقیت والجواہر۔(1)\n§عبداللہ بن عمرو بن حرام رضی اللہ عنہ کی شہادت\nسیدنا جابر رضی اللہ عنہ فرماتے ہیں کہ میرے باپ جنگ احد میں شہید ہوئے۔ کافروں نے ان کا مثلہ کیا۔ جب ان کی لاش رسول اللہ صلی اللہ علیہ وسلم کے سامنے لا کر رکھی تو میں نے اپنے باپ کے منہ سے کپڑا اٹھا کر دیکھنا چاہا مگر صحابہ نے مجھے منع کر دیا۔ میں نے دوبارہ دیکھنا چاہا تو صحابہ نے پھر منع کر دیا۔ تاہم رسول اللہ صلی اللہ علیہ وسلم نے مجھے اجازت دے دی۔\nاس سانحے پر میری پھوپھی فاطمہ بنت عمرو بہت رونے لگیں تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿وَلِمَ تَبْكِي؟ فَمَا زَالَتِ الْمَلَائِكَةُ تُظِلُّهُ بِأَجْنِحَتِهَا حَتَّى رُفِعَ﴾\n’’کیوں روتی ہو؟ جب تک ان کی میت پڑی رہی ہے فرشتوں نے اس پر اپنے پروں کا سایہ کیے رکھا ہے حتی کہ انھیں (تدفین کے لیے) اٹھا لیا گیا۔‘‘(2)\nایک روایت میں ہے:\n﴿تَبْكِينَ، أَوْ لَا تَبْكِينَ مَا زَالَتِ الْمَلَائِكَةُ تُظِلُّهُ بِأَجْنِحَتِهَا حَتَّى رَفَعْتُمُوهُ﴾\n’’تمھارے رونے یا نہ رونے سے کیا ہوگا؟ جب تک تم لوگوں نے انھیں اٹھا نہیں لیا، ان پر فرشتوں نے برابر","",{"v":600299,"fn":"(1) سيرة المصطفى صلى الله عليه وسلم از محمد ادریس کاندھلوی: 247,248/2\n(2) صحیح مسلم: 2471"}],[2875,"اپنے پروں کا سایہ کیے رکھا۔‘‘(1)\nسیدنا جابر رضی اللہ عنہ فرماتے ہیں کہ ایک روز رسول اللہ صلی اللہ علیہ وسلم نے مجھے دیکھ کر دریافت فرمایا: ﴿يَا جَابِرُ! مَا لِي أَرَاكَ مُنْكَسِرًا؟﴾ ’’اے جابر! تجھے کیا ہوا، میں تجھ کو شکستہ خاطر پاتا ہوں؟‘‘ میں نے عرض کیا: یا رسول اللہ! میرے باپ اس غزوہ میں شہید ہوئے اور آل و عیال اور قرض کا بار چھوڑ گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿أَلَا أُبَشِّرُكَ بِمَا لَقِيَ اللَّهُ بِهِ أَبَاكَ؟﴾\n’’کیا میں تمھیں خوشخبری نہ دوں کہ اللہ تعالیٰ نے تمھارے والد سے کس انداز سے ملاقات کی ہے؟‘‘ میں نے عرض کیا ضرور بتائیے۔ آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿يَا جَابِرُ! أَمَا عَلِمْتَ أَنَّ اللهَ عَزَّ وَجَلَّ أَحْيَا أَبَاكَ، فَقَالَ لَهُ: تَمَنَّ عَلَيَّ، فَقَالَ: أُرَدُّ إِلَى الدُّنْيَا، فَأُقْتَلَ مَرَّةً أُخْرَى، فَقَالَ: إِنِّي قَضَيْتُ، أَنَّهُمْ إِلَيْهَا لَا يُرْجَعُونَ﴾\n’’اے جابر! کیا تو جانتا ہے کہ اللہ عزوجل نے تیرے باپ کو زندہ فرمایا اور اس سے کہا: تمھاری کوئی تمنا ہو تو میرے سامنے بیان کرو۔ تب اس نے عرض کی: اے اللہ! مجھے دنیا میں بھیج دے تاکہ میں دوبارہ (تیرے رستے میں جہاد کروں اور) شہید کر دیا جاؤں۔ اللہ تبارک و تعالیٰ نے فرمایا: نہیں، میں نے تو فیصلہ کر رکھا ہے کہ لوگ دنیا میں دوبارہ نہیں بھیجے جائیں گے۔‘‘\nایک دوسری روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے سیدنا جابر رضی اللہ عنہ سے فرمایا:\n﴿مَا كَلَّمَ اللهُ أَحَدًا قَطُّ إِلَّا مِنْ وَرَاءِ حِجَابٍ، وَكَلَّمَ أَبَاكَ كِفَاحًا، فَقَالَ: يَا عَبْدِي، تَمَنَّ عَلَيَّ أُعْطِكَ، قَالَ: يَا رَبِّ، تُحْيِينِي فَأُقْتَلَ فِيكَ ثَانِيَةً، قَالَ: إِنَّهُ سَبَقَ مِنِّي أَنَّهُمْ إِلَيْهَا لَا يُرْجَعُونَ. قَالَ: يَا رَبِّ، فَأَبْلِغْ مَنْ وَرَائِي، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ هَذِهِ الْآيَةَ: وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ﴾ (آل عمران 3:169)\n’’کسی شخص سے اللہ نے کلام نہیں فرمایا مگر پس پردہ رہ کر مگر تیرے باپ کو اللہ نے زندہ فرمایا اور اس سے براہ راست گفتگو فرمائی اور کہا: اے میرے بندے! تیری کوئی تمنا ہو تو میرے سامنے پیش کر، میں وہ پوری کروں گا۔ اس نے عرض کیا: اے پروردگار! میری تڑپ یہ ہے کہ تو مجھے زندہ کر دے اور میں تیری راہ","",{"v":600300,"fn":"(1) صحیح البخاري: 1244 و 1293 و 2816، صحیح مسلم: 2471"}],[2876,"میں دوبارہ مارا جاؤں۔ اللہ تعالیٰ نے فرمایا: ایسا نہیں ہو سکتا، اس لیے کہ یہ مقدر کیا جا چکا ہے کہ مرنے کے بعد دوبارہ دنیا میں واپسی نہیں ہوگی۔ اس نے کہا: اے اللہ! پھر میرے پیچھے رہ جانے والوں کو میرے حال سے آگاہ فرما دے۔ تب اللہ تعالیٰ نے یہ آیت نازل فرمائی: ’’اور ان لوگوں کو ہرگز مردہ خیال نہ کرو جو اللہ کے راستے میں مارے گئے ہیں بلکہ وہ زندہ ہیں، انھیں ان کے رب کے ہاں رزق دیا جاتا ہے۔‘‘(1)\nایک اور جگہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿جَزَى اللهُ الْأَنْصَارَ عَنَّا خَيْرًا وَلَا سِيَّمَا عَبْدَ اللهِ بْنَ عَمْرِو بْنِ حَرَامٍ وَسَعْدَ بْنَ عُبَادَةَ﴾\n’’اللہ تعالیٰ انصار کو جزائے خیر دے، خاص طور پر ان میں سے عبداللہ بن عمرو بن حرام اور سعد بن عبادہ (رضی اللہ عنہما) کو۔‘‘(2)\n§عمرو بن جموح رضی اللہ عنہ کی شہادت\nسیدنا عبداللہ بن عمرو بن حرام رضی اللہ عنہ کے بہنوئی سیدنا عمرو بن جموح رضی اللہ عنہ بھی شہید ہوئے۔ سیدنا عمرو کے پاؤں میں لنگڑاہٹ تھی۔ ان کے چار بیٹے تھے۔ وہ ہر غزوے میں رسول اللہ صلی اللہ علیہ وسلم کے ہمرکاب رہتے تھے۔ احد کے غزوے میں بیٹوں نے باپ سے التماس کی کہ آپ کا عذر شرعی ہے۔ آپ جہاد میں شریک نہ ہوں لیکن شوق شہادت میں وہ رسول اللہ صلی اللہ علیہ وسلم سے عرض گزار ہوئے:\n﴿يَا رَسُولَ اللهِ! إِنَّ بَنِيَّ هَؤُلَاءِ يَمْنَعُونِي أَنْ أَخْرُجَ مَعَكَ، وَاللهِ! إِنِّي لَأَرْجُو أَنْ أُسْتَشْهَدَ فَأَطَأَ بِعَرْجَتِي هَذِهِ فِي الْجَنَّةِ﴾\n’’اے اللہ کے رسول! میرے بیٹے مجھے آپ کے ساتھ جہاد کے لیے نکلنے سے منع کر رہے ہیں۔ اللہ کی قسم! میں امید رکھتا ہوں کہ میں شہید کر دیا جاؤں گا اور اس لنگڑے پن کی حالت میں جنت کی زمین روندوں گا۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم نے انھیں اجازت مرحمت فرما دی۔ انھوں نے مدینہ سے چلتے ہوئے یہ دعا کی:\n﴿اللَّهُمَّ ارْزُقْنِي الشَّهَادَةَ وَلَا تَرُدَّنِي إِلَى أَهْلِي خَائِبًا﴾\n’’اے اللہ! مجھ کو شہادت نصیب فرما اور مجھے میرے گھر والوں کی طرف نامراد مت لوٹانا۔‘‘(3)","",{"v":600301,"fn":"(1) جامع الترمذي: 3010، السيرة لابن هشام: 127/3، البداية والنهاية: 45/4\n(2) صحيح ابن حبان: 487/15، المستدرك للحاكم: 111,112/4، إمتاع الأسماع: 290/7\n(3) دلائل النبوة للبيهقي: 246/3، السيرة لابن هشام: 96/3"}],[2877,"اللہ تبارک و تعالیٰ نے ان کی یہ دعا قبول فرمائی۔ انھیں احد کے موقع پر شہادت سے سرفراز فرمایا۔ اسی طرح ان کے ایک بیٹے خلاد بن عمرو رضی اللہ عنہ کو بھی اللہ تعالیٰ نے شہادت نصیب فرمائی۔\nسیدنا عمرو بن جموح رضی اللہ عنہ کی بیوی ہند بنت عمرو بن حرام رضی اللہ عنہا نے، جو سیدنا جابر رضی اللہ عنہ کی پھوپھی تھیں، یہ ارادہ کیا کہ تینوں، یعنی اپنے بھائی عبداللہ بن عمرو بن حرام، اپنے خاوند عمرو بن جموح اور اپنے بیٹے خلاد بن عمرو بن جموح رضی اللہ عنہم کو ایک اونٹ پر سوار کر کے مدینہ لے جائیں اور تینوں کو وہیں دفن کریں، چنانچہ انھوں نے تینوں کی لاشوں کو اونٹ پر رکھا اور مدینہ روانہ ہو گئیں۔ رستے میں ام المؤمنین سیدہ عائشہ رضی اللہ عنہا سے ملاقات ہوئی۔ وہ خواتین کے ساتھ غزوہ احد کی معلومات لینے کے لیے نکلی تھیں۔ انھوں نے سیدہ ہند بنت عمرو سے پوچھا:\n﴿عِنْدَكِ الْخَبَرُ، فَمَا وَرَاءَكِ؟﴾\n’’آپ جہاں سے آ رہی ہیں، وہاں کی کیا خبر ہے؟‘‘\nہند بنت عمرو نے جواب دیا:\n﴿خَيْرًا، أَمَّا رَسُولُ اللهِ فَصَالِحٌ وَكُلُّ مُصِيبَةٍ بَعْدَهُ جَلَلٌ، وَاتَّخَذَ اللهُ مِنَ الْمُؤْمِنِينَ شُهَدَاءَ، وَرَدَّ اللهُ الَّذِينَ كَفَرُوا بِغَيْظِهِمْ لَمْ يَنَالُوا خَيْرًا، وَكَفَى اللهُ الْمُؤْمِنِينَ الْقِتَالَ وَكَانَ اللهُ قَوِيًّا عَزِيزًا﴾\n’’نہایت اچھی خبر ہے۔ رسول اللہ صلی اللہ علیہ وسلم بخیریت ہیں۔ ان کی خیر و عافیت کے بعد ہر مصیبت بے ضرر ہے، البتہ اللہ تعالیٰ نے مومنین میں سے شہداء کو قبول فرمایا ہے اور کفار کو اللہ تعالیٰ نے رسوا کر کے لوٹا دیا ہے؟ انھیں کوئی خیر نصیب نہیں ہوئی۔ اللہ تعالیٰ لڑائی میں مومنین کی طرف سے کافی ہو گیا۔ اور اللہ تعالیٰ نہایت قوی اور غالب ہے۔‘‘\nسیدہ عائشہ رضی اللہ عنہا نے پوچھا: لیکن یہ کون ہیں جنھیں آپ اٹھائے لیے جا رہی ہیں؟ ہند بنت عمرو رضی اللہ عنہا کہنے لگیں: (یہ شہدائے احد میں سے ہیں) میرا بھائی، میرا بیٹا اور میرا خاوند عمرو بن جموح۔ سیدہ عائشہ رضی اللہ عنہا نے پوچھا: آپ انھیں کہاں لے جا رہی ہیں؟ ہند کہنے لگیں: میں انھیں مدینہ لے جا رہی ہوں، انھیں وہیں دفن کروں گی۔ پھر اونٹ کو اٹھایا تو وہ بیٹھ گیا۔\nسیدہ عائشہ رضی اللہ عنہا نے پوچھا: اس اونٹ کو کیا ہو گیا ہے؟ انھوں نے کہا: میں جونہی مدینہ کا قصد کرتی ہوں تو اونٹ بیٹھ جاتا ہے اور جب احد کا رخ کرتی ہوں تو یہ تیز چلنے لگتا ہے۔","",{"v":600302}],[2878,"بالآخر ہند بنت عمرو رسول اللہ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئی اور آپ صلی اللہ علیہ وسلم کو اس صورت حال سے مطلع کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿فَإِنَّ الْجَمَلَ مَأْمُورٌ، هَلْ قَالَ شَيْئًا؟﴾\n’’اونٹ مامور ہے۔ کیا عمرو بن جموح نے کچھ کہا تھا؟‘‘ ہند کہنے لگی: عمرو بن جموح رضی اللہ عنہ نے احد کی طرف جاتے ہوئے کہا تھا:\n﴿اللَّهُمَّ لَا تَرُدَّنِي إِلَى أَهْلِي خِزْيًا وَارْزُقْنِي الشَّهَادَةَ﴾\n’’اے اللہ! مجھے میرے گھر کی طرف رسوا کر کے نہ لوٹانا۔ مجھے شہادت سے سرفراز فرمانا۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\n﴿فَلِذَلِكَ الْجَمَلُ لَا يَمْضِي، إِنَّ مِنْكُمْ يَا مَعْشَرَ الْأَنْصَارِ! مَنْ لَوْ أَقْسَمَ عَلَى اللهِ لَأَبَرَّهُ، يَا هِنْدُ! مَا زَالَتِ الْمَلَائِكَةُ مُظِلَّةً عَلَى أَخِيكِ مِنْ لَدُنْ قُتِلَ إِلَى السَّاعَةِ يَنْظُرُونَ أَيْنَ يُدْفَنُ﴾\n’’اسی لیے اونٹ نہیں چل رہا۔ اے انصار کے گروہ! تم میں ایسے لوگ بھی ہیں کہ اگر اللہ پر قسم ڈالیں تو اللہ تعالیٰ ان کی قسم پوری فرماتا ہے۔ اے ہند! فرشتے تیرے بھائی پر، جب سے وہ شہید ہوا، اس وقت سے اب تک سایہ کیے ہوئے ہیں۔ وہ دیکھ رہے ہیں کہ انھیں کہاں دفن کیا جاتا ہے۔‘‘\nپھر رسول اللہ صلی اللہ علیہ وسلم ٹھہرے رہے یہاں تک کہ انھیں دفن کر دیا گیا۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿قَدْ تَرَافَقُوا فِي الْجَنَّةِ جَمِيعًا، عَمْرُو بْنُ الْجَمُوحِ، وَابْنُكِ خَلَّادٌ وَأَخُوكِ عَبْدُ اللهِ﴾\n’’اے ہند! (تیرا خاوند) عمرو بن جموح، تیرا بیٹا خلاد اور تیرا بھائی عبداللہ جنت میں اکٹھے ہیں۔‘‘\nہند کہنے لگی:\n﴿يَا رَسُولَ اللهِ! ادْعُ اللهَ عَسَى أَنْ يَجْعَلَنِي مَعَهُمْ﴾\n’’اے اللہ کے رسول! اللہ سے دعا فرمائیے کہ مجھے بھی ان کا ساتھ نصیب کر دے۔‘‘(1)\nرسول اللہ صلی اللہ علیہ وسلم نے ان کی تدفین کے بارے میں فرمایا:","",{"v":600303,"fn":"(1) [ضعيف] المغازي للواقدي: 266/1، إمتاع الأسماع: 161,162/1۔ صحیح بات وہی ہے جو آگے مسند أحمد (397,398/3) کی صحیح حدیث میں بیان ہوئی ہے۔"}],[2879,"﴿ادْفِنُوا عَبْدَ اللهِ بْنَ عَمْرِو بْنِ حَرَامٍ وَعَمْرَو بْنَ الْجَمُوحِ فِي قَبْرٍ وَاحِدٍ﴾\n’’عبداللہ بن عمرو بن حرام اور عمرو بن جموح رضی اللہ عنہما کو ایک ہی قبر میں دفن کرو۔‘‘\nرسول اللہ صلی اللہ علیہ وسلم نے مزید فرمایا:\n﴿ادْفِنُوا هَذَيْنِ الْمُتَحَابَّيْنِ فِي الدُّنْيَا فِي قَبْرٍ وَاحِدٍ﴾\n’’دنیا میں یہ دونوں گہرے دوست تھے، انھیں ایک ہی قبر میں دفن کرو۔‘‘(1)\nامام احمد رحمہ اللہ سے روایت ہے کہ سیدنا جابر بن عبداللہ رضی اللہ عنہما نے بیان کیا کہ میرے والد احد میں شہید ہو گئے۔ میری بہنوں نے اپنا اونٹ دے کر مجھے ان کی طرف بھیجا اور کہا: جا اور اس اونٹ پر اپنے باپ کی میت اٹھا لا، پھر انھیں بنو سلمہ کے قبرستان میں دفن کر دے۔ سیدنا جابر رضی اللہ عنہ فرماتے ہیں: میں اور میرے ساتھی جب عبداللہ بن عمرو کی لاش کے پاس گئے تو رسول اللہ صلی اللہ علیہ وسلم کو بھی اس کی اطلاع پہنچ گئی۔ آپ احد میں بیٹھے ہوئے تھے۔ آپ صلی اللہ علیہ وسلم نے مجھے بلایا اور فرمایا:\n﴿وَالَّذِي نَفْسِي بِيَدِهِ لَا يُدْفَنُ إِلَّا مَعَ إِخْوَتِهِ﴾\n’’اس ذات کی قسم جس کے قبضے میں میری جان ہے! وہ اپنے بھائیوں ہی کے ساتھ دفن ہوگا۔‘‘(2)\nچنانچہ انھیں اپنے اصحاب کے ساتھ احد میں دفن کر دیا گیا۔\nاسی طرح ایک اور روایت ہے کہ سیدنا جابر فرماتے ہیں کہ میں دیکھنے والوں میں شامل تھا۔ میں نے دیکھا کہ اچانک میری پھوپھی، میرے باپ اور ماموں کو لے آئی ہیں۔ انھوں نے ان دونوں کو اونٹ پر برابر برابر کر کے سوار کیا ہوا تھا۔ وہ ان دونوں کو مدینہ لائیں تا کہ انھیں ہمارے قبرستان میں دفن کر دیں۔ اچانک ایک شخص یہ منادی کرتا ہوا ملا:\n﴿أَلَا إِنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكُمْ أَنْ تَرْجِعُوا بِالْقَتْلَى فَتَدْفِنُوهَا فِي مَصَارِعِهَا حَيْثُ قُتِلَتْ﴾\n’’آگاہ رہو! نبی کریم صلی اللہ علیہ وسلم تمھیں حکم دیتے ہیں کہ تم اپنے مقتولین احد کو واپس احد لے جاؤ اور وہیں دفن کرو جہاں وہ شہید ہوئے ہیں۔‘‘\nچنانچہ ہم انھیں واپس لے گئے اور جہاں وہ شہید ہوئے تھے، ہم نے انھیں وہیں دفن کر دیا۔(3)","",{"v":600304,"fn":"(1) دلائل النبوة للبيهقي: 293/3، المغازي للواقدي: 243/1\n(2) [ضعیف] مسند أحمد: 396/3\n(3) مسند أحمد: 397,398/3"}],[2880,"§اصیرم رضی اللہ عنہ کی شہادت\nسیدنا عمرو بن ثابت بن وقش (اُقَیْش) جو اصیرم کے لقب سے مشہور تھے، ہمیشہ اسلام سے دور رہے۔ احد کے روز جب مشرکین مکہ نے مسلمانوں پر یلغار کی تو اللہ تبارک و تعالیٰ نے ان کے دل کو اسلام کے نور سے بھر دیا۔\nسیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ عمرو بن ثابت بن اقیش (وقش) جاہلیت میں لوگوں سے سود وصول کرتے تھے، اس لیے سود کی وصول یابی سے پہلے انھوں نے مسلمان ہونا پسند نہ کیا۔ احد کے دن کہیں سے گھر آئے تو پوچھا: فلاں کہاں ہے؟ جواب ملا: احد میں ہے۔ مزید دو تین لوگوں کے بارے میں پوچھا تو یہی جواب ملا کہ سب میدان احد میں ہیں، چنانچہ انھوں نے بھی زرہ پہنی، اسلحہ سنبھالا، گھوڑے پر سوار ہوئے اور سیدھے احد روانہ ہو گئے۔ مسلمانوں نے انھیں دیکھا تو کہنے لگے: تم یہاں سے چلے جاؤ، ہمیں تمھاری مدد کی کوئی ضرورت نہیں۔ وہ کہنے لگے: اب میں ایمان لا چکا ہوں۔ پھر وہ لڑتے رہے حتی کہ زخمی ہو گئے۔ زخمی حالت میں انھیں گھر لایا گیا۔ سیدنا سعد بن معاذ رضی اللہ عنہ آئے اور اپنی بہن سے کہا: اس سے پوچھو یہ کس بنا پر لڑا ہے؟ قومی حمیت کے لیے یا اللہ کے لیے غضبناک ہو کر؟ انھوں نے جواب دیا: میں اللہ اور اس کے رسول صلی اللہ علیہ وسلم کے لیے لڑا ہوں۔ یہ کہہ کر وہ اسی وقت فوت ہو گئے۔ انھیں ایک نماز پڑھنے کا بھی موقع نہیں ملا۔(1)\nایک روایت میں ہے کہ سیدنا اصیرم عمرو بن ثابت بن وقش رضی اللہ عنہ تلوار لے کر مشرکین سے خوب لڑے یہاں تک کہ زخمی ہو کر گر پڑے۔ مسلمانوں کو ان کے اسلام کی مطلق خبر نہیں تھی۔ جب انھوں نے اصیرم رضی اللہ عنہ کو دیکھا کہ وہ کمال بہادری سے لڑے اور لڑتے لڑتے ہی زخمی ہو کر گر پڑے ہیں تو انھیں بہت تعجب ہوا۔ انھوں نے پوچھا:\n﴿مَا جَاءَ بِكَ يَا عَمْرُو! أَحَرْبًا عَلَى قَوْمِكَ، أَوْ رَغْبَةً فِي الْإِسْلَامِ؟﴾\n’’اے عمرو! تجھے اس قتال پر کس چیز نے اکسایا ہے؟ اسلام کی رغبت نے یا قومی غیرت و حمیت نے؟‘‘\nاصیرم رضی اللہ عنہ نے جواب دیا:\n﴿بَلْ رَغْبَةً فِي الْإِسْلَامِ، آمَنْتُ بِاللهِ وَبِرَسُولِهِ وَأَسْلَمْتُ ثُمَّ أَخَذْتُ سَيْفِي، فَغَدَوْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَاتَلْتُ حَتَّى أَصَابَنِي مَا أَصَابَنِي﴾\n’’مجھے اسلام کی رغبت نے قتال پر مجبور کیا۔ میں اللہ اور اس کے رسول پر ایمان لایا ہوں اور اسلام قبول کر چکا ہوں۔ میں نے تلوار سونتی اور رسول اللہ صلی اللہ علیہ وسلم کے ساتھ شامل ہو کر اسلام کے دشمنوں سے قتال کیا","",{"v":600305,"fn":"(1) سنن أبي داود: 2537، السيرة لابن هشام: 95/3، الإصابة: 501/4"}],[2881,"حتی کہ میں زخمی ہو گیا۔‘‘\nاس کے بعد وہ شہید ہو گئے۔ رسول اللہ صلی اللہ علیہ وسلم کو جب عمرو بن ثابت رضی اللہ عنہ کے بارے میں اطلاع دی گئی تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿إِنَّهُ لَمِنْ أَهْلِ الْجَنَّةِ﴾\n’’بلاشبہ اصیرم اہل جنت میں سے ہے۔‘‘\nایک دن سیدنا ابو ہریرہ رضی اللہ عنہ نے لوگوں سے پوچھا: ایسے جنتی کا نام بتاؤ جس نے ایک نماز بھی نہیں پڑھی، اس کے باوجود وہ جنتی ہے۔ لوگوں نے کہا: آپ ہی فرمائیے۔ انھوں نے فرمایا: وہ اصیرم ہے۔ وہ بنو عبد الاشہل کا فرد تھا۔(1)\n§شماس بن عثمان رضی اللہ عنہ کی جاں نثاری\nشماس بن عثمان بن الشرید مخزومی رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کا دفاع کرنے والوں میں شامل تھے۔ آپ صلی اللہ علیہ وسلم جب بھی دائیں یا بائیں دیکھتے تو شماس کو اپنی تلوار سے اپنی ذات بابرکات کا دفاع کرتے ہوئے پاتے۔ شماس نے اپنے جسم کو بھی رسول اللہ صلی اللہ علیہ وسلم کے تحفظ کے لیے ڈھال بنا دیا۔ وہ اسی طرح آپ صلی اللہ علیہ وسلم کی دفاعی خدمت انجام دیتے دیتے شہید ہو گئے۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کے بارے میں فرمایا:\n﴿مَا وَجَدْتُ لِشَمَّاسٍ شَبَهًا إِلَّا الْجُنَّةَ﴾\n’’اس روز میں نے شماس کو دیکھا کہ وہ ڈھال کی طرح میرا دفاع کر رہے تھے۔‘‘(2)\n§مخیریق کی غزوہ احد میں شرکت\nمخیریق یہود کے قبیلے بنو ثعلبہ بن فطیون سے تھے۔ ان کا ذکر سیرت انسائیکلوپیڈیا کی چوتھی جلد میں صفحہ 443 پر گزر چکا ہے۔ یہ رسول اللہ صلی اللہ علیہ وسلم کو ان نشانیوں کی روشنی میں خوب پہچانتے تھے جو تورات میں درج تھیں۔ لیکن وہ کھل کر اسلام قبول کرنے سے تامل کرتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم جب احد کے لیے نکلے تو یہ ہفتے کا دن تھا۔ اللہ تبارک و تعالیٰ نے مخیریق کا دل نبی کریم صلی اللہ علیہ وسلم کی محبت سے معمور فرما دیا۔ یہ اپنے قبیلے میں نہایت بارسوخ اور مالدار شخص تھے۔ انھوں نے احد کے روز اپنے گروہ یہود سے کہا: اے یہود کی جماعت! اللہ کی قسم! تم اچھی طرح جانتے ہو کہ محمد صلی اللہ علیہ وسلم کی مدد کرنا تم پر لازم ہے۔ وہ کہنے لگے: آج سبت (ہفتے کا دن) ہے۔ مخیریق فرمانے لگے:","",{"v":600306,"fn":"(1) مسند أحمد: 428,429/5\n(2) المغازي للواقدي: 227/1، إمتاع الأسماع: 158/1"}],[2882,"[تصویر: مخیریق سے منسوب باغ کا مبینہ مقام]\nتمھارے لیے ہفتے کی پابندی کرنا لازم نہیں۔ یہ کہہ کر انھوں نے اپنا اسلحہ اٹھایا اور اپنی قوم کو وصیت کی کہ اگر آج میں کام آ جاؤں تو میرا سارا مال محمد صلی اللہ علیہ وسلم کے حوالے کر دینا، میرا مال انھی کے لیے ہے، وہ جہاں چاہیں گے، اسے خرچ کریں گے۔ یہ تاکید فرما کر وہ میدان احد میں پہنچ گئے۔\nجب جنگ ہوئی تو مخیریق مشرکین سے دیوانہ وار لڑے اور لڑتے لڑتے اللہ کو پیارے ہو گئے۔ رسول اللہ صلی اللہ علیہ وسلم کو ان کی اطلاع دی گئی تو آپ صلی اللہ علیہ وسلم نے فرمایا:\n﴿مُخَيْرِيقٌ خَيْرُ يَهُودَ﴾\n’’مخیریق یہودیوں میں سب سے بہتر تھے۔‘‘(1)\n§قزمان کی بہادری\nلشکر اسلام جب مدینہ طیبہ سے روانہ ہوا تو اس وقت تک ابوالغیداق قزمان منافق لشکر میں شریک نہیں ہوا تھا۔ قزمان نہایت نامور دلیر انسان تھا، جنگی حربوں کا بڑا ماہر تھا۔ یہ مدینہ طیبہ کے ایک انصاری قبیلے بنو ظفر کا حلیف تھا۔","",{"v":600307,"fn":"(1) السيرة لابن هشام: 94/3، السيرة لابن كثير، ص: 310","im":["v6_p307.jpg"]}],[2883,"لیکن اس کی اصلیت کے بارے میں کسی کو کچھ علم نہ تھا کہ وہ کون ہے اور کس قبیلے سے ہے، تاہم اس کی بہادری اور فنون حرب میں مہارت کی وجہ سے اسے لوگ اچھی طرح جانتے تھے۔ نبی کریم صلی اللہ علیہ وسلم کے سامنے جب اس کا تذکرہ کیا جاتا تو آپ صلی اللہ علیہ وسلم فرماتے:\n﴿إِنَّهُ مِنْ أَهْلِ النَّارِ﴾\n’’بلاشبہ وہ جہنمی ہے۔‘‘\nجب لشکر اسلام مدینہ سے نکلا تو یہ اس میں شریک نہ ہوا۔ بنو ظفر کی عورتوں نے اسے عار دلائی کہ قزمان تمھیں تو اپنی بہادری پر بڑا ناز تھا۔ آج موقع آیا تو بزدلوں کی طرح گھر بیٹھ گئے۔ کیا تمھیں شرم نہیں آتی؟ چنانچہ عورتوں کے طعنے سن کر وہ میدان احد کی طرف چل دیا۔\nجب وہ میدان میں پہنچا تو نبی صلی اللہ علیہ وسلم صفیں درست کرا رہے تھے۔ وہ بھی پہلی صف میں جا کھڑا ہوا۔ جنگ شروع ہوئی تو سب سے پہلے اس نے مشرکین پر تیر چلایا۔ اس کے تیر عام تیروں کی نسبت بہت بڑے تھے۔ جب وہ اپنی کمان پر تیر رکھ کر چلاتا تو یوں لگتا تھا گویا وہ تیر نہیں نیزہ ہے اور تیر چلاتے وقت وہ اونٹ جیسی آواز بھی نکالتا تھا۔ تیر برسانے کے بعد اس نے شمشیر زنی شروع کر دی یہاں تک کہ اس نے سات یا نو مشرکین کو تہ تیغ کر دیا۔ اس دوران وہ خود بھی زخمی ہو گیا اور زخموں کی تاب نہ لا کر گر پڑا۔ سیدنا قتادہ بن نعمان رضی اللہ عنہ نے اسے دیکھ کر فرمایا:\n﴿يَا أَبَا الْغَيْدَاقِ! هَنِيئًا لَكَ الشَّهَادَةُ﴾\n’’اے ابوغیداق! تمھیں شہادت مبارک ہو۔‘‘\nاسی طرح دیگر مسلمان بھی اسے شاباش دینے لگے اور کہنے لگے:\n﴿وَاللهِ! لَقَدْ أَبْلَيْتَ الْيَوْمَ يَا قُزْمَانُ فَأَبْشِرْ﴾\n’’اللہ کی قسم! آج تو تم نے بہادری کے جھنڈے گاڑ دیے۔ تمھیں خوشخبری ہو۔‘‘ وہ کہنے لگا: مجھے کس چیز کی خوشخبری دیتے ہو؟\n﴿فَوَاللهِ! إِنْ قَاتَلْتُ إِلَّا عَنْ أَحْسَابِ قَوْمِي، وَلَوْلَا ذَلِكَ مَا قَاتَلْتُ﴾\n’’اللہ کی قسم! میں نے تو قومی غیرت کی وجہ سے لڑائی کی ہے۔ اگر یہ وجہ نہ ہوتی تو میں جنگ ہی نہ کرتا۔‘‘\nایک روایت کے مطابق اس نے یہ الفاظ کہے:","",{"v":600308}]])